enum emergency_warp_physical_failure {
	EMERGENCY_WARP_PHYSICAL_OK,
	EMERGENCY_WARP_PHYSICAL_GET,
	EMERGENCY_WARP_PHYSICAL_PUT,
};

enum sector_mine_physical_failure {
	SECTOR_MINE_PHYSICAL_OK,
	SECTOR_MINE_PHYSICAL_ENTRY_PLAYER_GET,
	SECTOR_MINE_PHYSICAL_ENTRY_NEWS,
	SECTOR_MINE_PHYSICAL_BATCH_SECTOR_GET,
	SECTOR_MINE_PHYSICAL_BATCH_SECTOR_PUT,
	SECTOR_MINE_PHYSICAL_BATCH_PLAYER_GET,
	SECTOR_MINE_PHYSICAL_PRE_PUT_PLAYER_GET,
	SECTOR_MINE_PHYSICAL_PLAYER_PUT,
	SECTOR_MINE_PHYSICAL_FINAL_NEWS,
	SECTOR_MINE_PHYSICAL_FINAL_SECTOR_GET,
};

struct hostile_mines_hazard_fixture {
	struct main_mines_cycle_fixture cycle;
	struct yt_sector_mine_state hazard;
	struct yt_player hazard_player;
	struct yt_sector hazard_sector;
	int hazard_logical_sector;
	struct yt_player emergency_player;
	float draws[512];
	size_t draw_position;
	enum sector_mine_physical_failure mine_failure;
	unsigned mine_error_number;
	unsigned mine_saved_ip;
	bool mine_error_requested;
	struct yt_gameplay_hazard_error_request mine_error_request;
	size_t mine_start;
	size_t current_read_attempts;
	size_t current_reads;
	size_t player_read_attempts;
	size_t player_reads;
	size_t player_write_attempts;
	size_t player_writes;
	size_t sector_read_attempts;
	size_t sector_reads;
	size_t sector_write_attempts;
	size_t sector_writes;
	float sounds[2];
	size_t sound_count;
	uint8_t news[2][96];
	size_t news_lengths[2];
	size_t news_attempts;
	size_t news_count;
	bool shrink_called;
	bool shrink_enabled;
	float shrink_result;
	bool warp_called;
	size_t warp_calls;
	size_t emergency_warp_start;
	bool compose_emergency_player_from_hazard;
	bool enable_emergency_warp;
	enum emergency_warp_physical_failure emergency_failure;
	size_t emergency_failure_warp;
	size_t emergency_player_reads;
	size_t emergency_player_put_attempts;
	size_t emergency_player_writes;
	size_t emergency_flushes;
	size_t emergency_waits;
	unsigned emergency_error_number;
	unsigned emergency_saved_ip;
	bool emergency_error_requested;
	struct yt_gameplay_hazard_error_request emergency_error_request;
	float emergency_destination;
	float emergency_cost;
	float emergency_sector_cache;
	float emergency_heat;
	size_t emergency_ticks;
	bool destroyed;
	unsigned reentry_failure;
	unsigned reentry_error_number;
	unsigned reentry_saved_ip;
	bool reentry_warning_carrier_failure;
	bool reentry_warning_second_carrier_failure;
	bool reentry_warning_carrier_ended;
};

static bool
hostile_mine_hazard_fail(struct hostile_mines_hazard_fixture *fixture,
    enum sector_mine_physical_failure failure)
{
	if (fixture->mine_failure != failure)
		return false;
	if (!yt_gameplay_hazard_error_project(fixture->mine_error_number,
	    fixture->mine_saved_ip, &fixture->mine_error_request))
		return true;
	fixture->mine_error_requested = true;
	return true;
}

static bool
hostile_mine_hazard_read_current(void *context, struct yt_player *player,
    struct yt_error *error)
{
	struct hostile_mines_hazard_fixture *fixture = context;
	enum sector_mine_physical_failure failure;

	(void)error;
	if (player == NULL)
		return false;
	++fixture->current_read_attempts;
	failure = fixture->current_read_attempts == 1U
	    ? SECTOR_MINE_PHYSICAL_ENTRY_PLAYER_GET
	    : SECTOR_MINE_PHYSICAL_BATCH_PLAYER_GET;
	if (hostile_mine_hazard_fail(fixture, failure))
		return false;
	*player = fixture->hazard_player;
	++fixture->current_reads;
	return true;
}

static bool
hostile_mine_hazard_read_player(void *context, int player_record,
    struct yt_player *player, struct yt_error *error)
{
	struct hostile_mines_hazard_fixture *fixture = context;

	(void)error;
	if (player_record != 2 || player == NULL)
		return false;
	++fixture->player_read_attempts;
	if (hostile_mine_hazard_fail(fixture,
	    SECTOR_MINE_PHYSICAL_PRE_PUT_PLAYER_GET))
		return false;
	*player = fixture->hazard_player;
	++fixture->player_reads;
	return true;
}

static bool
hostile_mine_hazard_write_player(void *context, int player_record,
    struct yt_player *player, struct yt_error *error)
{
	struct hostile_mines_hazard_fixture *fixture = context;

	(void)error;
	if (player_record != 2 || player == NULL)
		return false;
	++fixture->player_write_attempts;
	if (hostile_mine_hazard_fail(fixture,
	    SECTOR_MINE_PHYSICAL_PLAYER_PUT))
		return false;
	fixture->hazard_player = *player;
	++fixture->player_writes;
	return true;
}

static bool
hostile_mine_hazard_read_sector(void *context, int logical_sector,
    struct yt_sector *sector, struct yt_error *error)
{
	struct hostile_mines_hazard_fixture *fixture = context;
	enum sector_mine_physical_failure failure;

	(void)error;
	if (logical_sector != fixture->hazard_logical_sector || sector == NULL)
		return false;
	++fixture->sector_read_attempts;
	failure = fixture->sector_read_attempts == 1U
	    ? SECTOR_MINE_PHYSICAL_BATCH_SECTOR_GET
	    : SECTOR_MINE_PHYSICAL_FINAL_SECTOR_GET;
	if (hostile_mine_hazard_fail(fixture, failure))
		return false;
	*sector = fixture->hazard_sector;
	++fixture->sector_reads;
	return true;
}

static bool
hostile_mine_hazard_write_sector(void *context, int logical_sector,
    struct yt_sector *sector, struct yt_error *error)
{
	struct hostile_mines_hazard_fixture *fixture = context;

	(void)error;
	if (logical_sector != fixture->hazard_logical_sector || sector == NULL)
		return false;
	++fixture->sector_write_attempts;
	if (hostile_mine_hazard_fail(fixture,
	    SECTOR_MINE_PHYSICAL_BATCH_SECTOR_PUT))
		return false;
	fixture->hazard_sector = *sector;
	++fixture->sector_writes;
	return true;
}

static bool
hostile_mine_hazard_present(void *context, const uint8_t *text,
    size_t length, enum yt_sector_mine_output_kind kind,
    struct yt_error *error)
{
	struct hostile_mines_hazard_fixture *fixture = context;
	struct viewer_pager_join *join = fixture->cycle.presentation.viewer != NULL
	    ? &fixture->cycle.presentation.viewer->join : NULL;
	struct yt_present_result result;
	enum yt_present_status status;

	(void)error;
	if (join == NULL)
		return false;
	switch (kind) {
	case YT_SECTOR_MINE_OUTPUT_LINE:
		status = yt_present_line(text, length, &join->presentation, &result);
		break;
	case YT_SECTOR_MINE_OUTPUT_BOLD_LINE:
		status = yt_present_bold_line(text, length, &join->presentation,
		    &result);
		break;
	case YT_SECTOR_MINE_OUTPUT_BOLD_RAW:
		status = yt_present_bold_character(text, length, &join->presentation,
		    &result);
		break;
	default:
		return false;
	}
	if (status != YT_PRESENT_OK)
		return false;
	viewer_pager_capture_result(join, &result);
	return true;
}

static bool
hostile_mine_hazard_sound(void *context, float selector,
    struct yt_error *error)
{
	struct hostile_mines_hazard_fixture *fixture = context;
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;
	struct yt_present_result result;

	(void)error;
	if (fixture->sound_count >= YT_ARRAY_LEN(fixture->sounds)
	    || (selector != 5.0f && selector != 2.0f)
	    || yt_present_sound(selector, &join->presentation, &result)
	    != YT_PRESENT_OK)
		return false;
	fixture->sounds[fixture->sound_count++] = selector;
	viewer_pager_capture_result(join, &result);
	return true;
}

static bool
hostile_mine_hazard_news(void *context, const uint8_t *text, size_t length,
    struct yt_error *error)
{
	struct hostile_mines_hazard_fixture *fixture = context;
	enum sector_mine_physical_failure failure;

	(void)error;
	if (fixture->news_count >= YT_ARRAY_LEN(fixture->news)
	    || length > sizeof(fixture->news[0]))
		return false;
	++fixture->news_attempts;
	failure = fixture->news_attempts == 1U
	    ? SECTOR_MINE_PHYSICAL_ENTRY_NEWS
	    : SECTOR_MINE_PHYSICAL_FINAL_NEWS;
	if (hostile_mine_hazard_fail(fixture, failure))
		return false;
	memcpy(fixture->news[fixture->news_count], text, length);
	fixture->news_lengths[fixture->news_count] = length;
	++fixture->news_count;
	return true;
}

static bool
hostile_mine_hazard_random(void *context, float *value,
    struct yt_error *error)
{
	struct hostile_mines_hazard_fixture *fixture = context;

	(void)error;
	if (value == NULL || fixture->draw_position >= YT_ARRAY_LEN(fixture->draws))
		return false;
	*value = fixture->draws[fixture->draw_position++];
	return true;
}

static bool
hostile_mine_hazard_shrink(void *context, float range, float *result,
    struct yt_error *error)
{
	struct hostile_mines_hazard_fixture *fixture = context;

	(void)range;
	(void)error;
	fixture->shrink_called = true;
	if (!fixture->shrink_enabled || result == NULL)
		return false;
	*result = fixture->shrink_result;
	return true;
}

static bool
hostile_mine_emergency_attention(struct hostile_mines_hazard_fixture *fixture,
    const uint8_t *text, size_t length)
{
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;
	struct yt_present_result result;

	if (yt_present_attention(text, length, &join->presentation, &result)
	    != YT_PRESENT_OK)
		return false;
	viewer_pager_capture_result(join, &result);
	return true;
}

static bool
hostile_mine_emergency_set_foreground(
    struct hostile_mines_hazard_fixture *fixture, float foreground)
{
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;

	join->presentation.foreground = foreground;
	join->pager.foreground = (int)foreground;
	return true;
}

static bool
hostile_emergency_warp_present(struct hostile_mines_hazard_fixture *fixture)
{
	static const uint8_t title[] = " * EMERGENCY WARP ENGAGED! * ";
	static const uint8_t wormhole[] =
	    "You enter a wormhole as your engines build up to emergency power!";
	static const uint8_t temperature[] = "     * Engine Temperature *";
	static const uint8_t scale[] = "[ Normal ][ Danger ][ Overheat ]";
	static const uint8_t ruler[] = "================================";
	static const uint8_t gauge_open[] = "[";
	static const uint8_t gauge_tick[] = "*";
	static const uint8_t relief[] =
	    "You sigh in relief as you look at your scanner and find yourself in";
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;
	struct yt_present_result result;
	float first;
	float second;
	float duration;
	float tick_draw;
	float destination_draw;
	float override_draw;
	float turn_draw;
	uint8_t row[160];
	size_t row_length;

	if (!hostile_mine_hazard_present(fixture, NULL, 0U,
	    YT_SECTOR_MINE_OUTPUT_LINE, NULL)
	    || !hostile_mine_emergency_attention(fixture, title,
	    sizeof(title) - 1U)
	    || !hostile_mine_hazard_present(fixture, NULL, 0U,
	    YT_SECTOR_MINE_OUTPUT_LINE, NULL)
	    || !hostile_mine_hazard_present(fixture, wormhole,
	    sizeof(wormhole) - 1U, YT_SECTOR_MINE_OUTPUT_BOLD_LINE, NULL)
	    || !hostile_mine_hazard_present(fixture, NULL, 0U,
	    YT_SECTOR_MINE_OUTPUT_LINE, NULL)
	    || !hostile_mine_emergency_set_foreground(fixture, 6.0f)
	    || !hostile_mine_hazard_present(fixture, temperature,
	    sizeof(temperature) - 1U, YT_SECTOR_MINE_OUTPUT_BOLD_LINE, NULL)
	    || !hostile_mine_hazard_present(fixture, scale,
	    sizeof(scale) - 1U, YT_SECTOR_MINE_OUTPUT_BOLD_LINE, NULL)
	    || !hostile_mine_emergency_set_foreground(fixture, 2.0f)
	    || !hostile_mine_hazard_present(fixture, ruler,
	    sizeof(ruler) - 1U, YT_SECTOR_MINE_OUTPUT_BOLD_LINE, NULL)
	    || !hostile_mine_emergency_set_foreground(fixture, 6.0f)
	    || !hostile_mine_hazard_present(fixture, gauge_open,
	    sizeof(gauge_open) - 1U, YT_SECTOR_MINE_OUTPUT_BOLD_RAW, NULL)
	    || !hostile_mine_hazard_random(fixture, &first, NULL)
	    || !hostile_mine_hazard_random(fixture, &second, NULL))
		return false;
	duration = yt_emergency_warp_duration(first, second);
	if (duration != 0.0f
	    || !hostile_mine_hazard_random(fixture, &tick_draw, NULL))
		return false;
	if (tick_draw > 0.75f)
		fixture->emergency_heat += 1.0f;
	if (!hostile_mine_emergency_set_foreground(fixture,
	    fixture->emergency_heat < 10.0f ? 2.0f
	    : fixture->emergency_heat < 20.0f ? 3.0f : 1.0f)
	    || !hostile_mine_hazard_present(fixture, gauge_tick,
	    sizeof(gauge_tick) - 1U, YT_SECTOR_MINE_OUTPUT_BOLD_RAW, NULL))
		return false;
	++fixture->emergency_ticks;
	++fixture->emergency_waits;
	if (!hostile_mine_emergency_set_foreground(fixture, 2.0f)
	    || !hostile_mine_hazard_present(fixture, NULL, 0U,
	    YT_SECTOR_MINE_OUTPUT_LINE, NULL)
	    || !hostile_mine_hazard_present(fixture, NULL, 0U,
	    YT_SECTOR_MINE_OUTPUT_LINE, NULL))
		return false;
	++fixture->emergency_player_reads;
	if (fixture->emergency_failure == EMERGENCY_WARP_PHYSICAL_GET
	    && (fixture->emergency_failure_warp == 0U
	    || fixture->emergency_failure_warp == fixture->warp_calls)) {
		if (!yt_gameplay_hazard_error_project(
		    fixture->emergency_error_number, fixture->emergency_saved_ip,
		    &fixture->emergency_error_request))
			return false;
		fixture->emergency_error_requested = true;
		return false;
	}
	if (!hostile_mine_hazard_random(fixture, &destination_draw, NULL)
	    || !hostile_mine_hazard_random(fixture, &override_draw, NULL)
	    || !hostile_mine_hazard_random(fixture, &turn_draw, NULL))
		return false;
	fixture->emergency_destination = yt_emergency_warp_destination(
	    destination_draw, 2004.0f);
	if (override_draw > 0.949999988079071f)
		fixture->emergency_destination = 733.0f;
	fixture->emergency_cost = yt_emergency_warp_cost(fixture->emergency_heat,
	    turn_draw, fixture->emergency_player.turns, false);
	if (yt_present_sound(1.0f, &join->presentation, &result) != YT_PRESENT_OK)
		return false;
	viewer_pager_capture_result(join, &result);
	if (!hostile_mine_hazard_present(fixture, relief, sizeof(relief) - 1U,
	    YT_SECTOR_MINE_OUTPUT_LINE, NULL)
	    || !yt_emergency_warp_result_row(fixture->emergency_destination,
	    fixture->emergency_cost, row, sizeof(row), &row_length)
	    || !hostile_mine_hazard_present(fixture, row, row_length,
	    YT_SECTOR_MINE_OUTPUT_LINE, NULL))
		return false;
	yt_emergency_warp_player_overlay(&fixture->emergency_player,
	    fixture->emergency_destination, fixture->emergency_cost);
	++fixture->emergency_player_put_attempts;
	if (fixture->emergency_failure == EMERGENCY_WARP_PHYSICAL_PUT
	    && (fixture->emergency_failure_warp == 0U
	    || fixture->emergency_failure_warp == fixture->warp_calls)) {
		if (!yt_gameplay_hazard_error_project(
		    fixture->emergency_error_number, fixture->emergency_saved_ip,
		    &fixture->emergency_error_request))
			return false;
		fixture->emergency_error_requested = true;
		return false;
	}
	fixture->hazard_player = fixture->emergency_player;
	++fixture->emergency_player_writes;
	++fixture->emergency_flushes;
	fixture->emergency_sector_cache = fixture->emergency_destination;
	return true;
}

static bool
hostile_mine_hazard_warp(void *context, struct yt_error *error)
{
	struct hostile_mines_hazard_fixture *fixture = context;
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;
	bool completed;

	(void)error;
	if (fixture->compose_emergency_player_from_hazard)
		fixture->emergency_player = fixture->hazard_player;
	fixture->warp_called = true;
	++fixture->warp_calls;
	fixture->emergency_warp_start = join->remote_length;
	completed = fixture->enable_emergency_warp
	    && hostile_emergency_warp_present(fixture);
	if (completed && fixture->compose_emergency_player_from_hazard)
		fixture->hazard_player = fixture->emergency_player;
	return completed;
}

static void
hostile_mine_hazard_set_current(void *context,
    const struct yt_player *player)
{
	struct hostile_mines_hazard_fixture *fixture = context;

	fixture->hazard_player = *player;
}

static void
hostile_mine_hazard_style(void *context, float foreground, float background,
    float blink, int pager_foreground)
{
	struct hostile_mines_hazard_fixture *fixture = context;
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;

	join->presentation.foreground = foreground;
	join->presentation.background = background;
	join->presentation.blink = blink;
	join->pager.foreground = pager_foreground;
}

