enum direct_warp_invalid_boundary_kind {
	DIRECT_WARP_INVALID_EXHAUSTED,
	DIRECT_WARP_INVALID_INACTIVITY,
	DIRECT_WARP_INVALID_SESSION_LIMIT,
};

struct direct_warp_invalid_boundary_state {
	struct hostile_mines_hazard_fixture *fixture;
	uint8_t output_scratch[80];
	size_t output_length;
	uint8_t prompt_scratch[80];
	size_t prompt_length;
	bool boundary_required;
	bool running;
	bool terminated;
	bool closed_all;
};

static bool
direct_warp_invalid_terminal_notice(void *context, const uint8_t *notice,
    size_t length)
{
	struct direct_warp_invalid_boundary_state *state = context;
	struct viewer_pager_join *join =
	    &state->fixture->cycle.presentation.viewer->join;

	if (length > sizeof(state->output_scratch)
	    || length > sizeof(join->source))
		return false;
	memcpy(state->output_scratch, notice, length);
	state->output_length = length;
	memcpy(join->source, notice, length);
	join->source_length = length;
	return normal_exit_line(join, NULL, 0U)
	    && normal_exit_b05d(join, notice, length, 0.0f);
}

static bool
direct_warp_invalid_terminal_close(void *context)
{
	struct direct_warp_invalid_boundary_state *state = context;

	state->closed_all = true;
	return true;
}

static bool
direct_emergency_warp_invalid_boundary_continue(
    struct hostile_mines_hazard_fixture *fixture,
    enum direct_warp_invalid_boundary_kind kind,
    struct direct_warp_invalid_boundary_state *boundary)
{
	static const uint8_t warning_one[] =
	    "This is a desperate move! Your engines will be drained and will take time";
	static const uint8_t warning_two[] =
	    "to recharge! You also risk a melt down! Are you sure you wish to do this?";
	static const uint8_t prompt[] = "[y/N] -=> ";
	static const uint8_t invalid[] = "X";
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;
	struct yt_present_result result;
	enum yt_yes_no_answer answer;
	char output[80];
	enum yt_ab36_terminal_kind terminal;

	if (boundary == NULL)
		return false;
	if (yt_present_color(&join->presentation, &result) != YT_PRESENT_OK
	    || !normal_exit_line(join, NULL, 0U))
		return false;
	join->presentation.bold = 1.0f;
	join->presentation.foreground = 7.0f;
	join->pager.foreground = 7;
	if (!normal_exit_b05d(join, warning_one, sizeof(warning_one) - 1U, 0.0f))
		return false;
	join->presentation.bold = 1.0f;
	if (!normal_exit_b05d(join, warning_two, sizeof(warning_two) - 1U, 0.0f)
	    || !normal_exit_line(join, NULL, 0U))
		return false;
	memcpy(boundary->prompt_scratch, prompt, sizeof(prompt) - 1U);
	boundary->prompt_length = sizeof(prompt) - 1U;
	join->presentation.bold = 1.0f;
	if (yt_present_character(prompt, sizeof(prompt) - 1U,
	    &join->presentation, &result) != YT_PRESENT_OK)
		return false;
	viewer_pager_capture_result(join, &result);
	yt_pager_editor_enter(&join->pager, join->accumulator,
	    sizeof(join->accumulator));
	memcpy(join->accumulator, invalid, sizeof(invalid));
	if (yt_present_editor_echo(invalid, sizeof(invalid) - 1U,
	    invalid, sizeof(invalid) - 1U, &join->presentation, &result)
	    != YT_PRESENT_OK)
		return false;
	viewer_pager_capture_result(join, &result);
	if (!normal_exit_line(join, NULL, 0U)
	    || !yt_input_yes_no_candidate(join->accumulator, output,
	    sizeof(output), &answer) || answer != YT_YES_NO_INVALID)
		return false;
	memcpy(boundary->output_scratch, output, 2U);
	boundary->output_length = 1U;
	memcpy(join->source, output, 2U);
	join->source_length = 1U;
	join->presentation.bold = 1.0f;
	if (!yt_input_queue_clear(join->queue, sizeof(join->queue),
	    &join->queue_position, &join->queue_length))
		return false;
	if (kind == DIRECT_WARP_INVALID_EXHAUSTED) {
		boundary->boundary_required = true;
		return true;
	}
	if (yt_present_character(prompt, sizeof(prompt) - 1U,
	    &join->presentation, &result) != YT_PRESENT_OK)
		return false;
	viewer_pager_capture_result(join, &result);
	yt_pager_editor_enter(&join->pager, join->accumulator,
	    sizeof(join->accumulator));
	terminal = kind == DIRECT_WARP_INVALID_INACTIVITY
	    ? YT_AB36_TERMINAL_INACTIVITY : YT_AB36_TERMINAL_SESSION_LIMIT;
	return yt_input_ab36_terminal_run(terminal, &boundary->running,
	    &boundary->terminated, direct_warp_invalid_terminal_notice,
	    direct_warp_invalid_terminal_close, boundary);
}

static bool
direct_emergency_warp_invalid_boundary_run(
    struct hostile_mines_hazard_fixture *fixture, bool ansi,
    enum direct_warp_invalid_boundary_kind kind,
    struct direct_warp_invalid_boundary_state *boundary)
{
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;

	if (boundary == NULL)
		return false;
	memset(boundary, 0, sizeof(*boundary));
	boundary->fixture = fixture;
	boundary->running = true;
	join->presentation = state(ansi);
	return direct_emergency_warp_invalid_boundary_continue(fixture, kind,
	    boundary);
}

static void
test_direct_emergency_warp_invalid_boundaries(void)
{
	static const uint8_t invalid[] = "X";
	static const uint8_t prompt[] = "[y/N] -=> ";
	static const uint8_t inactivity[] = "\aUSER FELL ASLEEP!";
	static const uint8_t session_limit[] =
	    "\a\a\aTIME LIMIT EXCEEDED!\a\a\a";
	static const struct {
		bool ansi;
		enum direct_warp_invalid_boundary_kind kind;
		size_t expected_length;
		uint64_t expected_hash;
		const uint8_t *output;
		size_t output_length;
		size_t rows;
		uint64_t row_hash;
		size_t colors;
		uint64_t color_hash;
		float bold;
		float cached_foreground;
		size_t events;
	} cases[] = {
		{false, DIRECT_WARP_INVALID_EXHAUSTED, 167U,
		    UINT64_C(0x83bb08430714c2ac), invalid, sizeof(invalid) - 1U,
		    5U, UINT64_C(0x2beabdb4c35912a6), 2U,
		    UINT64_C(0x6d3fa4669b3587bd), 1.0f, 2.0f, 10U},
		{true, DIRECT_WARP_INVALID_EXHAUSTED, 223U,
		    UINT64_C(0x0084a4372833a813), invalid, sizeof(invalid) - 1U,
		    5U, UINT64_C(0x2beabdb4c35912a6), 8U,
		    UINT64_C(0x844da71c138d59e8), 1.0f, 7.0f, 10U},
		{false, DIRECT_WARP_INVALID_INACTIVITY, 199U,
		    UINT64_C(0x39915733cce99840), inactivity,
		    sizeof(inactivity) - 1U, 7U, UINT64_C(0xc7c22a1456128ac0),
		    3U, UINT64_C(0x2207a27a6260aaca), 1.0f, 2.0f, 15U},
		{true, DIRECT_WARP_INVALID_INACTIVITY, 277U,
		    UINT64_C(0xdb3deea4a03ffba7), inactivity,
		    sizeof(inactivity) - 1U, 7U, UINT64_C(0xc7c22a1456128ac0),
		    12U, UINT64_C(0x626155b42fa5e310), 0.0f, 7.0f, 15U},
		{false, DIRECT_WARP_INVALID_SESSION_LIMIT, 207U,
		    UINT64_C(0xf53cee7d0b46b832), session_limit,
		    sizeof(session_limit) - 1U, 7U, UINT64_C(0x9911d7488e9b1826),
		    3U, UINT64_C(0x2207a27a6260aaca), 1.0f, 2.0f, 15U},
		{true, DIRECT_WARP_INVALID_SESSION_LIMIT, 285U,
		    UINT64_C(0xc69e1ae5a22cbdb9), session_limit,
		    sizeof(session_limit) - 1U, 7U, UINT64_C(0x9911d7488e9b1826),
		    12U, UINT64_C(0x626155b42fa5e310), 0.0f, 7.0f, 15U},
	};
	struct physical_viewer_join viewer;
	struct yt_file_viewer_stream_state stream;
	struct hostile_mines_hazard_fixture fixture;
	struct direct_warp_invalid_boundary_state boundary;
	uint8_t remote[320];
	size_t pass;

	for (pass = 0U; pass < YT_ARRAY_LEN(cases); ++pass) {
		memset(&viewer, 0, sizeof(viewer));
		fixture_viewer_initialize(&viewer, &stream,
		    retained_scoreboard, sizeof(retained_scoreboard) - 1U,
		    "YTSCORE.ASC", cases[pass].ansi, remote, sizeof(remote));
		memset(&fixture, 0, sizeof(fixture));
		fixture.cycle.presentation.viewer = &viewer;
		CHECK(direct_emergency_warp_invalid_boundary_run(&fixture,
		    cases[pass].ansi, cases[pass].kind, &boundary));
		CHECK(viewer.join.remote_length == cases[pass].expected_length
		    && viewer_bytes_fnv1a64(remote, viewer.join.remote_length)
		    == cases[pass].expected_hash
		    && boundary.output_length == cases[pass].output_length
		    && memcmp(boundary.output_scratch, cases[pass].output,
		    cases[pass].output_length) == 0
		    && boundary.prompt_length == sizeof(prompt) - 1U
		    && memcmp(boundary.prompt_scratch, prompt,
		    sizeof(prompt) - 1U) == 0
		    && boundary.boundary_required
		    == (cases[pass].kind == DIRECT_WARP_INVALID_EXHAUSTED)
		    && boundary.running
		    == (cases[pass].kind == DIRECT_WARP_INVALID_EXHAUSTED)
		    && boundary.terminated
		    == (cases[pass].kind != DIRECT_WARP_INVALID_EXHAUSTED)
		    && boundary.closed_all
		    == (cases[pass].kind != DIRECT_WARP_INVALID_EXHAUSTED)
		    && viewer.join.source_length == cases[pass].output_length
		    && memcmp(viewer.join.source, cases[pass].output,
		    cases[pass].output_length) == 0
		    && viewer.join.queue_position == 0U
		    && viewer.join.queue_length == 0U
		    && viewer.join.local_fragment_length == 0U
		    && viewer.join.local_row_count == cases[pass].rows
		    && viewer_rows_fnv1a64(&viewer.join) == cases[pass].row_hash
		    && viewer.join.local_color_count == cases[pass].colors
		    && viewer_colors_fnv1a64(&viewer.join)
		    == cases[pass].color_hash
		    && viewer.join.presentation.foreground == 7.0f
		    && viewer.join.presentation.background == 0.0f
		    && viewer.join.presentation.bold == cases[pass].bold
		    && viewer.join.presentation.blink == 0.0f
		    && viewer.join.presentation.cached_foreground
		    == cases[pass].cached_foreground
		    && viewer.join.pager.foreground == 7
		    && viewer.join.pager.line_count
		    == (cases[pass].kind == DIRECT_WARP_INVALID_EXHAUSTED
		    ? 0.0f : 1.0f)
		    && !fixture.warp_called && fixture.draw_position == 0U
		    && fixture.emergency_player_reads == 0U
		    && fixture.emergency_player_put_attempts == 0U
		    && fixture.emergency_player_writes == 0U
		    && fixture.emergency_flushes == 0U
		    && fixture.emergency_waits == 0U
		    && viewer.join.event_count == cases[pass].events);
		if (cases[pass].kind == DIRECT_WARP_INVALID_EXHAUSTED)
			CHECK(strcmp(viewer.join.accumulator, "X") == 0);
		else
			CHECK(viewer.join.accumulator[0] == '\0');
		yt_text_input_destroy(&viewer.input);
	}
}

enum direct_warp_parent_copy_failure {
	DIRECT_WARP_FAIL_WARNING_ONE,
	DIRECT_WARP_FAIL_WARNING_TWO,
	DIRECT_WARP_FAIL_PROMPT,
};

struct direct_warp_parent_copy_state {
	uint8_t output_scratch[80];
	size_t output_length;
	uint8_t prompt_scratch[80];
	size_t prompt_length;
	enum direct_warp_parent_copy_failure failure;
	bool routed_main_handler;
};

static bool
direct_emergency_warp_parent_copy_failure_continue(
    struct hostile_mines_hazard_fixture *fixture,
    enum direct_warp_parent_copy_failure failure,
    struct direct_warp_parent_copy_state *copy)
{
	static const uint8_t warning_one[] =
	    "This is a desperate move! Your engines will be drained and will take time";
	static const uint8_t warning_two[] =
	    "to recharge! You also risk a melt down! Are you sure you wish to do this?";
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;
	struct yt_present_result result;

	if (copy == NULL)
		return false;
	copy->failure = failure;
	copy->routed_main_handler = false;
	if (yt_present_color(&join->presentation, &result) != YT_PRESENT_OK
	    || !normal_exit_line(join, NULL, 0U))
		return false;
	if (failure == DIRECT_WARP_FAIL_WARNING_ONE) {
		copy->routed_main_handler = true;
		return true;
	}
	memcpy(copy->output_scratch, warning_one, sizeof(warning_one) - 1U);
	copy->output_length = sizeof(warning_one) - 1U;
	join->presentation.bold = 1.0f;
	join->presentation.foreground = 7.0f;
	join->pager.foreground = 7;
	if (!normal_exit_b05d(join, warning_one, sizeof(warning_one) - 1U, 0.0f))
		return false;
	if (failure == DIRECT_WARP_FAIL_WARNING_TWO) {
		copy->routed_main_handler = true;
		return true;
	}
	memcpy(copy->output_scratch, warning_two, sizeof(warning_two) - 1U);
	copy->output_length = sizeof(warning_two) - 1U;
	join->presentation.bold = 1.0f;
	if (!normal_exit_b05d(join, warning_two, sizeof(warning_two) - 1U, 0.0f)
	    || !normal_exit_line(join, NULL, 0U))
		return false;
	copy->routed_main_handler = true;
	return true;
}

static bool
direct_emergency_warp_parent_copy_failure_run(
    struct hostile_mines_hazard_fixture *fixture, bool ansi,
    enum direct_warp_parent_copy_failure failure,
    struct direct_warp_parent_copy_state *copy)
{
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;

	if (copy == NULL)
		return false;
	memcpy(copy->output_scratch, "old-output", 10U);
	copy->output_length = 10U;
	memcpy(copy->prompt_scratch, "old-prompt", 10U);
	copy->prompt_length = 10U;
	join->presentation = state(ansi);
	return direct_emergency_warp_parent_copy_failure_continue(fixture,
	    failure, copy);
}

static void
test_direct_emergency_warp_parent_copy_failures(void)
{
	static const uint8_t warning_one[] =
	    "This is a desperate move! Your engines will be drained and will take time";
	static const uint8_t warning_two[] =
	    "to recharge! You also risk a melt down! Are you sure you wish to do this?";
	static const uint8_t plain_warning_two[] =
	    "\r\n"
	    "This is a desperate move! Your engines will be drained and will take time\n\r";
	static const uint8_t plain_prompt[] =
	    "\r\n"
	    "This is a desperate move! Your engines will be drained and will take time\n\r"
	    "to recharge! You also risk a melt down! Are you sure you wish to do this?\n\r"
	    "\r\n";
	static const uint8_t ansi_warning_two[] =
	    "\r\n"
	    "\x1b[0;37;40;1m"
	    "This is a desperate move! Your engines will be drained and will take time\n\r";
	static const uint8_t ansi_prompt[] =
	    "\r\n"
	    "\x1b[0;37;40;1m"
	    "This is a desperate move! Your engines will be drained and will take time\n\r"
	    "\x1b[0;37;40;1m"
	    "to recharge! You also risk a melt down! Are you sure you wish to do this?\n\r"
	    "\x1b[0;37;40m\r\n";
	static const struct {
		bool ansi;
		enum direct_warp_parent_copy_failure failure;
		const uint8_t *expected;
		size_t expected_length;
		const uint8_t *output;
		size_t output_length;
	} cases[] = {
		{false, DIRECT_WARP_FAIL_WARNING_ONE,
		    (const uint8_t *)"\r\n", 2U,
		    (const uint8_t *)"old-output", 10U},
		{true, DIRECT_WARP_FAIL_WARNING_ONE,
		    (const uint8_t *)"\r\n", 2U,
		    (const uint8_t *)"old-output", 10U},
		{false, DIRECT_WARP_FAIL_WARNING_TWO,
		    plain_warning_two, sizeof(plain_warning_two) - 1U,
		    warning_one, sizeof(warning_one) - 1U},
		{true, DIRECT_WARP_FAIL_WARNING_TWO,
		    ansi_warning_two, sizeof(ansi_warning_two) - 1U,
		    warning_one, sizeof(warning_one) - 1U},
		{false, DIRECT_WARP_FAIL_PROMPT,
		    plain_prompt, sizeof(plain_prompt) - 1U,
		    warning_two, sizeof(warning_two) - 1U},
		{true, DIRECT_WARP_FAIL_PROMPT,
		    ansi_prompt, sizeof(ansi_prompt) - 1U,
		    warning_two, sizeof(warning_two) - 1U},
	};
	struct physical_viewer_join viewer;
	struct yt_file_viewer_stream_state stream;
	struct hostile_mines_hazard_fixture fixture;
	struct direct_warp_parent_copy_state copy;
	uint8_t remote[256];
	size_t pass;

	for (pass = 0U; pass < YT_ARRAY_LEN(cases); ++pass) {
		memset(&viewer, 0, sizeof(viewer));
		fixture_viewer_initialize(&viewer, &stream,
		    retained_scoreboard, sizeof(retained_scoreboard) - 1U,
		    "YTSCORE.ASC", cases[pass].ansi, remote, sizeof(remote));
		memset(&fixture, 0, sizeof(fixture));
		fixture.cycle.presentation.viewer = &viewer;
		memset(&copy, 0, sizeof(copy));
		CHECK(direct_emergency_warp_parent_copy_failure_run(&fixture,
		    cases[pass].ansi, cases[pass].failure, &copy));
		CHECK(viewer.join.remote_length == cases[pass].expected_length
		    && memcmp(remote, cases[pass].expected,
		    cases[pass].expected_length) == 0
		    && copy.failure == cases[pass].failure
		    && copy.routed_main_handler
		    && copy.output_length == cases[pass].output_length
		    && memcmp(copy.output_scratch, cases[pass].output,
		    cases[pass].output_length) == 0
		    && copy.prompt_length == 10U
		    && memcmp(copy.prompt_scratch, "old-prompt", 10U) == 0
		    && !fixture.warp_called && fixture.draw_position == 0U
		    && fixture.emergency_player_reads == 0U
		    && fixture.emergency_player_writes == 0U
		    && fixture.emergency_flushes == 0U
		    && fixture.emergency_waits == 0U);
		yt_text_input_destroy(&viewer.input);
	}
}

static bool
direct_emergency_warp_hostile_menu_prefix(
    struct hostile_mines_hazard_fixture *fixture, bool ansi,
    const uint8_t *command, size_t command_length, size_t *end)
{
	static const uint8_t prompt[] =
	    "Option? (A,B,D,I,Q,S,T,W,?=Help):? ";
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;
	uint8_t row[96];
	size_t row_length;
	char transformed[4];

	if (command == NULL || command_length == 0U
	    || command_length >= sizeof(transformed) || end == NULL)
		return false;
	join->presentation = state(ansi);
	join->presentation.foreground = 3.0f;
	join->pager.foreground = 3;
	if (!yt_hostile_menu_row(1000.0, 1250.0, row, sizeof(row), &row_length)
	    || !normal_exit_line(join, NULL, 0U)
	    || !normal_exit_b05d(join, row, row_length, 0.0f)
	    || !normal_exit_b05d(join, prompt, sizeof(prompt) - 1U, 1.0f))
		return false;
	yt_pager_editor_enter(&join->pager, join->accumulator,
	    sizeof(join->accumulator));
	memcpy(join->accumulator, command, command_length);
	join->accumulator[command_length] = '\0';
	if (!main_buy_present_echo(&fixture->cycle.presentation, command,
	    command_length) || !normal_exit_line(join, NULL, 0U))
		return false;
	*end = join->remote_length;
	memcpy(transformed, command, command_length);
	transformed[command_length] = '\0';
	yt_input_compat_upper_n_observed((uint8_t *)transformed,
	    command_length, NULL, NULL);
	return yt_hostile_menu_dispatch(transformed) == YT_HOSTILE_MENU_WARP;
}

static bool
direct_emergency_warp_main_command_prefix(
    struct hostile_mines_hazard_fixture *fixture, bool ansi, size_t *end)
{
	static const uint8_t main_prompt[] =
	    "Time: 14:59  Main Command (?=Help)? ";
	static const uint8_t command[] = "W";
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;

	if (end == NULL)
		return false;
	join->presentation = state(ansi);
	join->presentation.color_initialized = 1.0f;
	join->presentation.cached_foreground = 2.0f;
	join->pager.foreground = 2;
	if (!normal_exit_line(join, NULL, 0U)
	    || !normal_exit_b05d(join, main_prompt,
	    sizeof(main_prompt) - 1U, 1.0f))
		return false;
	yt_pager_editor_enter(&join->pager, join->accumulator,
	    sizeof(join->accumulator));
	memcpy(join->accumulator, command, sizeof(command));
	if (!main_buy_present_echo(&fixture->cycle.presentation, command,
	    sizeof(command) - 1U) || !normal_exit_line(join, NULL, 0U))
		return false;
	*end = join->remote_length;
	return true;
}

enum direct_warp_gate_get_failure {
	DIRECT_WARP_GATE_SEEK_52,
	DIRECT_WARP_GATE_READ_57,
	DIRECT_WARP_GATE_READ_70,
	DIRECT_WARP_GATE_READ_75,
};

struct direct_warp_gate_get_state {
	struct yt_database database;
	struct yt_record field;
	struct yt_record read_source;
	int field_record;
	bool field_player;
	enum direct_warp_gate_get_failure failure;
	bool read_success;
	size_t accepted;
	size_t seek_calls;
	size_t read_calls;
	int64_t terminal_position;
	int64_t last_seek_offset;
};

static bool
direct_warp_gate_seek(void *context, FILE *file, int64_t absolute_offset,
    struct yt_database_seek_observation *observation)
{
	struct direct_warp_gate_get_state *state = context;

	(void)file;
	++state->seek_calls;
	state->last_seek_offset = absolute_offset;
	memset(observation, 0, sizeof(*observation));
	observation->terminal_position = state->terminal_position;
	if (!state->read_success
	    && state->failure == DIRECT_WARP_GATE_SEEK_52) {
		observation->carry = true;
		observation->dos_error = 6U;
	}
	else
		observation->terminal_position = absolute_offset;
	return true;
}

static bool
direct_warp_gate_read(void *context, FILE *file, uint8_t *data,
    size_t requested, struct yt_database_read_observation *observation)
{
	struct direct_warp_gate_get_state *state = context;

	(void)file;
	++state->read_calls;
	memset(observation, 0, sizeof(*observation));
	if (state->accepted > requested)
		return false;
	memcpy(data, state->read_source.bytes, state->accepted);
	observation->accepted = state->accepted;
	if (state->read_success) {
		observation->terminal_position = state->last_seek_offset
		    + (int64_t)state->accepted;
		return true;
	}
	observation->carry = true;
	observation->dos_error = state->failure == DIRECT_WARP_GATE_READ_57
	    ? 6U : 5U;
	observation->mapped_error = state->failure == DIRECT_WARP_GATE_READ_70
	    ? 70U : state->failure == DIRECT_WARP_GATE_READ_75 ? 75U : 0U;
	observation->terminal_position = state->terminal_position;
	return true;
}

static bool
direct_warp_gate_read_player(void *context, int player_record,
    struct yt_player *player, struct yt_error *error)
{
	struct direct_warp_gate_get_state *state = context;
	struct yt_record field = state->field;
	size_t accepted = 0U;

	if (yt_database_random_get(&state->database, (size_t)player_record,
	    &field, &accepted, error)) {
		state->field = field;
		state->field_record = player_record;
		state->field_player = true;
		yt_player_decode(player, &field);
		return true;
	}
	if (state->database.last_get.outcome == YT_DATABASE_GET_READ_ERROR) {
		state->field = field;
		state->field_record = player_record;
		state->field_player = true;
	}
	(void)yt_error_attach_basic_fault_number(error,
	    YT_BASIC_FAULT_CURRENT_PLAYER_A41C_GET,
	    state->database.last_get.basic_error);
	return false;
}

static bool
direct_emergency_warp_gate_get_failure_run(
    struct hostile_mines_hazard_fixture *fixture, bool hostile, bool ansi,
    const uint8_t *command, size_t command_length,
    enum direct_warp_gate_get_failure failure,
    struct direct_warp_gate_get_state *gate,
    struct yt_basic_fault_projection *projection, size_t ends[2])
{
	static const uint8_t scanner_gate_raw[4] = {0x00U, 0x00U, 0x60U, 0x00U};
	static const uint8_t main_gate_raw[4] = {0x00U, 0x00U, 0x00U, 0x00U};
	const uint8_t *expected_gate_raw = hostile
	    ? scanner_gate_raw : main_gate_raw;
	struct yt_current_player_hydration_state hydration;
	struct yt_player before;
	struct yt_error error;
	float current_sector = 784.0f;
	float cloak_cache[4] = {-1.0f, -2.0f, 0.5f, -4.0f};
	uint8_t gate_raw[4];
	size_t index;

	if (gate == NULL || projection == NULL || ends == NULL)
		return false;
	memset(gate, 0, sizeof(*gate));
	gate->database.file = tmpfile();
	if (gate->database.file == NULL)
		return false;
	gate->failure = failure;
	gate->accepted = failure == DIRECT_WARP_GATE_SEEK_52 ? 0U : 3U;
	gate->terminal_position = failure == DIRECT_WARP_GATE_SEEK_52
	    ? INT64_C(0x11223344) : INT64_C(0x55667788);
	gate->field = fixture->emergency_player.record;
	gate->field_record = 2;
	gate->field_player = true;
	for (index = 0U; index < YT_RECORD_SIZE; ++index)
		gate->read_source.bytes[index] = (uint8_t)(index ^ 0x5aU);
	yt_database_set_seek_provider(&gate->database, direct_warp_gate_seek,
	    gate);
	yt_database_set_read_provider(&gate->database, direct_warp_gate_read,
	    gate);
	memcpy(gate_raw, expected_gate_raw, sizeof(gate_raw));
	if ((hostile && !direct_emergency_warp_hostile_menu_prefix(fixture,
	    ansi, command, command_length, &ends[0]))
	    || (!hostile && (command_length != 1U || command[0] != 'W'
	    || !direct_emergency_warp_main_command_prefix(fixture, ansi,
	    &ends[0])))) {
		yt_database_close(&gate->database);
		return false;
	}
	ends[1] = ends[0];
	before = fixture->emergency_player;
	memset(&hydration, 0, sizeof(hydration));
	hydration.player = &fixture->emergency_player;
	hydration.player_record = 2;
	hydration.current_sector_record = &current_sector;
	if (qb_mbf32_encode(51.0f, hydration.sector_record_offset_raw)
	    != QB_MBF_OK) {
		yt_database_close(&gate->database);
		return false;
	}
	yt_error_clear(&error);
	if (yt_current_player_hydrate_run(&hydration,
	    direct_warp_gate_read_player, gate, &error)
	    || !yt_basic_fault_project(&error, NULL, 0U, NULL, 0U, NULL, 0U,
	    projection)
	    || memcmp(&fixture->emergency_player, &before, sizeof(before)) != 0
	    || current_sector != 784.0f
	    || memcmp(cloak_cache,
	    (const float[4]){-1.0f, -2.0f, 0.5f, -4.0f},
	    sizeof(cloak_cache)) != 0
	    || memcmp(gate_raw, expected_gate_raw, sizeof(gate_raw)) != 0) {
		yt_database_close(&gate->database);
		return false;
	}
	return true;
}

