static bool
direct_emergency_warp_ade0_prefix_failure_continue(
    struct hostile_mines_hazard_fixture *fixture,
    enum yt_basic_fault_site target,
    struct yt_basic_fault_projection *projection)
{
	static const uint8_t warning_one[] =
	    "This is a desperate move! Your engines will be drained and will take time";
	static const uint8_t warning_two[] =
	    "to recharge! You also risk a melt down! Are you sure you wish to do this?";
	static const uint8_t prompt[] = "[y/N] -=> ";
	static const uint8_t submitted[] = "A";
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;
	struct yt_present_result result;
	struct yt_command_save_transform save;
	struct yt_repeat_prefix_transform prefix;
	struct yt_error error;
	char text[80] = "A";
	uint8_t upper[80] = "inherited";
	char queue[80] = "";
	char saved[80] = "SAVED";
	char output[80] = "warning-two";
	size_t queue_position = 0U;
	size_t queue_length = 0U;

	if (projection == NULL
	    || yt_present_color(&join->presentation, &result) != YT_PRESENT_OK
	    || !normal_exit_line(join, NULL, 0U))
		return false;
	join->presentation.bold = 1.0f;
	join->presentation.foreground = 7.0f;
	join->pager.foreground = 7;
	if (!normal_exit_b05d(join, warning_one, sizeof(warning_one) - 1U, 0.0f))
		return false;
	join->presentation.bold = 1.0f;
	if (!normal_exit_b05d(join, warning_two, sizeof(warning_two) - 1U, 0.0f)
	    || !normal_exit_line(join, NULL, 0U))
		return false;
	join->presentation.bold = 1.0f;
	if (yt_present_character(prompt, sizeof(prompt) - 1U,
	    &join->presentation, &result) != YT_PRESENT_OK)
		return false;
	viewer_pager_capture_result(join, &result);
	yt_pager_editor_enter(&join->pager, join->accumulator,
	    sizeof(join->accumulator));
	memcpy(join->accumulator, submitted, sizeof(submitted));
	if (yt_present_editor_echo(submitted, sizeof(submitted) - 1U,
	    submitted, sizeof(submitted) - 1U, &join->presentation, &result)
	    != YT_PRESENT_OK)
		return false;
	viewer_pager_capture_result(join, &result);
	if (!normal_exit_line(join, NULL, 0U))
		return false;
	if (target == YT_BASIC_FAULT_ADE0_SLASH_TEST_RIGHT_SPACE) {
		if (yt_input_command_save_staged(text, sizeof(text), queue,
		    sizeof(queue), &queue_position, &queue_length, saved,
		    sizeof(saved), output, sizeof(output), target, &save)
		    || !save.fault_valid || save.fault_site != target)
			return false;
	}
	else {
		if (!yt_input_command_save_staged(text, sizeof(text), queue,
		    sizeof(queue), &queue_position, &queue_length, saved,
		    sizeof(saved), output, sizeof(output),
		    YT_BASIC_FAULT_SITE_COUNT, &save)
		    || yt_input_repeat_prefix_staged((const uint8_t *)text,
		    strlen(text), upper, sizeof(upper), target, 1U, &prefix,
		    NULL, NULL) || !prefix.fault_valid
		    || prefix.fault_site != target)
			return false;
	}
	if (strcmp(text, "A") != 0 || strcmp(queue, "") != 0
	    || queue_position != 0U || queue_length != 0U
	    || strcmp(saved, "SAVED") != 0
	    || strcmp(output, "warning-two") != 0)
		return false;
	yt_error_clear(&error);
	error.status = YT_RANGE;
	if (!yt_error_attach_basic_fault_number(&error,
	    target, target == YT_BASIC_FAULT_UPPER_FRAME_STACK ? 7U : 14U)
	    || !yt_basic_fault_project(&error, NULL, 0U,
	    (const uint8_t *)"01/01/30", 8U,
	    (const uint8_t *)"12:34:56", 8U, projection))
		return false;
	return true;
}

static void
test_direct_emergency_warp_ade0_prefix_failures(void)
{
	static const struct {
		bool hostile;
		bool ansi;
		const uint8_t *command;
		size_t command_length;
		size_t caller_end;
		size_t expected_length;
		uint64_t expected_hash;
	} cases[] = {
		{true, false, (const uint8_t *)"W", 1U, 63U, 230U,
		    UINT64_C(0xb5f4f0e60121ac27)},
		{true, false, (const uint8_t *)"WT", 2U, 64U, 231U,
		    UINT64_C(0xa5530392cf894c97)},
		{true, true, (const uint8_t *)"W", 1U, 73U, 296U,
		    UINT64_C(0x04a7d696b12ff6a1)},
		{true, true, (const uint8_t *)"WT", 2U, 74U, 297U,
		    UINT64_C(0x2c15cf3768f16f47)},
		{false, false, (const uint8_t *)"W", 1U, 41U, 208U,
		    UINT64_C(0x17e3948531b4855f)},
		{false, true, (const uint8_t *)"W", 1U, 41U, 264U,
		    UINT64_C(0x889c68ed6b015e98)},
	};
	static const struct {
		enum yt_basic_fault_site site;
		uint16_t instruction;
		uint16_t saved_ip;
		uint16_t statement;
		uint16_t erl;
		uint16_t handler;
		enum yt_basic_fault_module module;
	} cuts[] = {
		{YT_BASIC_FAULT_ADE0_SLASH_TEST_RIGHT_SPACE,
		    0xADE7U, 0xADEAU, 0xADE1U, 36000U, 0xB2DAU,
		    YT_BASIC_FAULT_MAIN},
		{YT_BASIC_FAULT_ADE0_UPPER_SCRATCH_CLONE_SPACE,
		    0xAE4AU, 0xAE4DU, 0xAE44U, 36000U, 0xB2DAU,
		    YT_BASIC_FAULT_MAIN},
		{YT_BASIC_FAULT_UPPER_FRAME_STACK,
		    0x1D99U, 0x1D9CU, 0x1D96U, 610U, 0x45F7U,
		    YT_BASIC_FAULT_SHARED},
		{YT_BASIC_FAULT_UPPER_MID_COMPARE_STRING_SPACE,
		    0x1DC2U, 0x1DC5U, 0x1DB4U, 610U, 0x45F7U,
		    YT_BASIC_FAULT_SHARED},
		{YT_BASIC_FAULT_UPPER_MID_VALUE_STRING_SPACE,
		    0x1DE0U, 0x1DE3U, 0x1DD2U, 610U, 0x45F7U,
		    YT_BASIC_FAULT_SHARED},
		{YT_BASIC_FAULT_UPPER_CHR_STRING_SPACE,
		    0x1DEAU, 0x1DEDU, 0x1DD2U, 610U, 0x45F7U,
		    YT_BASIC_FAULT_SHARED},
	};
	struct physical_viewer_join viewer;
	struct yt_file_viewer_stream_state stream;
	struct hostile_mines_hazard_fixture fixture;
	struct yt_basic_fault_projection projection;
	struct yt_record record;
	uint8_t remote[320];
	size_t caller_end;
	size_t cut;
	size_t index;

	for (index = 0U; index < YT_ARRAY_LEN(cases); ++index) {
		for (cut = 0U; cut < YT_ARRAY_LEN(cuts); ++cut) {
		memset(&viewer, 0, sizeof(viewer));
		fixture_viewer_initialize(&viewer, &stream,
		    retained_scoreboard, sizeof(retained_scoreboard) - 1U,
		    "YTSCORE.ASC", cases[index].ansi, remote, sizeof(remote));
		memset(&fixture, 0, sizeof(fixture));
		fixture.cycle.presentation.viewer = &viewer;
		memset(&record, 0xa5, sizeof(record));
		(void)yt_record_set_number(&record, YT_F49, 17.0f);
		(void)yt_record_set_number(&record, YT_F57, 733.0f);
		yt_player_decode(&fixture.emergency_player, &record);
		fixture.hazard_player = fixture.emergency_player;
		CHECK((cases[index].hostile
		    && direct_emergency_warp_hostile_menu_prefix(&fixture,
		    cases[index].ansi, cases[index].command,
		    cases[index].command_length, &caller_end))
		    || (!cases[index].hostile
		    && direct_emergency_warp_main_command_prefix(&fixture,
		    cases[index].ansi, &caller_end)));
		CHECK(direct_emergency_warp_ade0_prefix_failure_continue(
		    &fixture, cuts[cut].site, &projection));
		CHECK(caller_end == cases[index].caller_end
		    && viewer.join.remote_length == cases[index].expected_length
		    && viewer_bytes_fnv1a64(remote, viewer.join.remote_length)
		    == cases[index].expected_hash
		    && projection.site
		    == cuts[cut].site
		    && projection.error_number
		    == (cuts[cut].site == YT_BASIC_FAULT_UPPER_FRAME_STACK
		    ? 7U : 14U)
		    && projection.identity->instruction == cuts[cut].instruction
		    && projection.identity->saved_ip == cuts[cut].saved_ip
		    && projection.identity->retry_statement == cuts[cut].statement
		    && projection.identity->source_line == cuts[cut].erl
		    && projection.identity->handler == cuts[cut].handler
		    && projection.identity->module == cuts[cut].module
		    && projection.disposition == YT_BASIC_FAULT_END
		    && (cuts[cut].module == YT_BASIC_FAULT_MAIN
		    ? projection.main.route == YT_MAIN_ERROR_FATAL
		    : projection.shared.route == YT_SHARED_ERROR_GENERIC));
		CHECK(strcmp(viewer.join.accumulator, "A") == 0
		    && viewer.join.queue_position == 0U
		    && viewer.join.queue_length == 0U
		    && !fixture.warp_called && fixture.draw_position == 0U
		    && fixture.emergency_player_reads == 0U
		    && fixture.emergency_player_writes == 0U
		    && fixture.emergency_flushes == 0U
		    && fixture.emergency_waits == 0U);
		yt_text_input_destroy(&viewer.input);
		}
	}
}

struct direct_warp_a8d2_failure_state {
	struct yt_a8d2_transform transform;
	struct yt_basic_fault_projection projection;
	char prompt[32];
	char output[80];
	bool projected;
};

static bool
direct_emergency_warp_a8d2_failure_continue(
    struct hostile_mines_hazard_fixture *fixture, const uint8_t *submitted,
    size_t submitted_length, enum yt_a8d2_fault_site target,
    uint16_t error_number, struct direct_warp_a8d2_failure_state *fault)
{
	static const uint8_t warning_one[] =
	    "This is a desperate move! Your engines will be drained and will take time";
	static const uint8_t warning_two[] =
	    "to recharge! You also risk a melt down! Are you sure you wish to do this?";
	static const char prompt[] = "[y/N] -=> ";
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;
	struct yt_present_result result;
	struct yt_error error;
	size_t prompt_length = sizeof(prompt) - 1U;

	if (fault == NULL || submitted == NULL || submitted_length == 0U
	    || submitted_length >= sizeof(join->accumulator)
	    || yt_present_color(&join->presentation, &result) != YT_PRESENT_OK
	    || !normal_exit_line(join, NULL, 0U))
		return false;
	memset(fault, 0, sizeof(*fault));
	memcpy(fault->prompt, prompt, sizeof(prompt));
	join->presentation.bold = 1.0f;
	join->presentation.foreground = 7.0f;
	join->pager.foreground = 7;
	if (!normal_exit_b05d(join, warning_one, sizeof(warning_one) - 1U,
	    0.0f))
		return false;
	join->presentation.bold = 1.0f;
	if (!normal_exit_b05d(join, warning_two, sizeof(warning_two) - 1U,
	    0.0f) || !normal_exit_line(join, NULL, 0U))
		return false;
	join->presentation.bold = 1.0f;
	if (yt_present_character((const uint8_t *)prompt, sizeof(prompt) - 1U,
	    &join->presentation, &result) != YT_PRESENT_OK)
		return false;
	viewer_pager_capture_result(join, &result);
	yt_pager_editor_enter(&join->pager, join->accumulator,
	    sizeof(join->accumulator));
	memcpy(join->accumulator, submitted, submitted_length);
	join->accumulator[submitted_length] = '\0';
	if (!yt_input_split_semicolon(join->accumulator, join->queue,
	    sizeof(join->queue), &join->queue_position, &join->queue_length)
	    || yt_present_editor_echo(submitted, submitted_length, submitted,
	    submitted_length, &join->presentation, &result) != YT_PRESENT_OK)
		return false;
	viewer_pager_capture_result(join, &result);
	if (!normal_exit_line(join, NULL, 0U)
	    || !yt_input_a8d2_staged(join->accumulator, fault->output,
	    sizeof(fault->output), (uint8_t *)fault->prompt,
	    sizeof(fault->prompt), &prompt_length, join->queue,
	    sizeof(join->queue), &join->queue_position,
	    &join->queue_length, &join->presentation.bold, target,
	    error_number, &fault->transform))
		return false;
	memcpy(join->source, fault->output, strlen(fault->output) + 1U);
	join->source_length = strlen(fault->output);
	if (fault->transform.outcome != YT_A8D2_BASIC_ERROR)
		return fault->transform.outcome == YT_A8D2_INTERNAL_FATAL;
	yt_error_clear(&error);
	error.status = YT_RANGE;
	fault->projected = yt_error_attach_basic_fault_number(&error,
	    YT_BASIC_FAULT_A8D2_LEFT_ONE, error_number)
	    && yt_basic_fault_project(&error, NULL, 0U,
	    (const uint8_t *)"01/01/30", 8U,
	    (const uint8_t *)"12:34:56", 8U, &fault->projection);
	return fault->projected;
}

