static bool
direct_emergency_warp_hostile_reentry(
    struct hostile_mines_hazard_fixture *fixture,
    struct direct_warp_main_cycle_state *cycle)
{
	static const uint8_t warning[] =
	    "You have to defeat the fighters before you can enter this sector.";
	static const struct sensor_join_output scanner[] = {
		{SENSOR_JOIN_LINE, NULL},
		{SENSOR_JOIN_LINE, "Sector: 1003"},
		{SENSOR_JOIN_BOLD_LINE,
		    "You detect the shimmering of a cloaking device!"},
		{SENSOR_JOIN_BOLD_LINE, "Other Ships: "},
		{SENSOR_JOIN_LINE,
		    "    Target - Fighters: 10 - Shields: 5"},
		{SENSOR_JOIN_BOLD_RAW, "Fighters in sector:"},
		{SENSOR_JOIN_LINE, " 10 (Belong to The Xannor)"},
		{SENSOR_JOIN_RAW, "Warps lead to:"},
		{SENSOR_JOIN_RAW, " 2"},
		{SENSOR_JOIN_RAW, ", 9"},
		{SENSOR_JOIN_LINE, NULL},
	};
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;
	struct yt_present_result result;
	float reveal_draw;
	size_t index;

	join->presentation.foreground = 1.0f;
	join->pager.foreground = 1;
	++cycle->sector_reads;
	cycle->physical_current_sector = 1054.0f;
	if (!hostile_mine_hazard_random(fixture, &reveal_draw, NULL)
	    || !yt_sector_cloak_revealed(reveal_draw, cycle->target_cloak))
		return false;
	for (index = 0U; index < YT_ARRAY_LEN(scanner); ++index) {
		if (!sensor_join_present(join, &scanner[index]))
			return false;
		if (index == 2U) {
			cycle->target_cloak = 0.0f;
			if (yt_present_sound(4.0f, &join->presentation, &result)
			    != YT_PRESENT_OK)
				return false;
			viewer_pager_capture_result(join, &result);
			++cycle->scanner_sound_calls;
		}
		if (index == 3U)
			++cycle->target_player_reads;
	}
	++cycle->scanner_final_player_reads;
	cycle->final_field_record = 2;
	cycle->final_field_player = true;
	++cycle->router_player_reads;
	++cycle->router_sector_reads;
	cycle->final_field_record = 1054;
	cycle->final_field_player = false;
	join->queue[0] = '\0';
	join->queue_position = 0U;
	join->queue_length = 0U;
	join->presentation.foreground = 3.0f;
	join->pager.foreground = 3;
	if (!normal_exit_line(join, NULL, 0U))
		return false;
	join->presentation.bold = 1.0f;
	join->presentation.blink = 1.0f;
	if (fixture->reentry_warning_carrier_failure
	    || fixture->reentry_warning_second_carrier_failure) {
		join->fail_at = join->event_count
		    + (fixture->reentry_warning_carrier_failure ? 1U : 4U);
		if (normal_exit_b05d(join, warning, sizeof(warning) - 1U,
		    0.0f))
			return false;
		fixture->reentry_warning_carrier_ended = true;
		return true;
	}
	return normal_exit_b05d(join, warning, sizeof(warning) - 1U, 0.0f);
}

static bool
direct_emergency_warp_fresh_hostile_menu_command(
    struct hostile_mines_hazard_fixture *fixture,
    struct direct_warp_main_cycle_state *cycle, const uint8_t *command,
    size_t command_length, enum yt_hostile_menu_route expected_route,
    double ship_fighters, double deployed_fighters)
{
	static const uint8_t prompt[] =
	    "Option? (A,B,D,I,Q,S,T,W,?=Help):? ";
	struct viewer_pager_join *join = &fixture->cycle.presentation.viewer->join;
	uint8_t row[96];
	size_t row_length;

	if (command == NULL || command_length == 0U
	    || command_length >= sizeof(join->accumulator))
		return false;

	++cycle->fresh_hostile_player_reads;
	cycle->fresh_hostile_player_get_completed = true;
	cycle->final_field_record = 2;
	cycle->final_field_player = true;
	join->presentation.foreground = 3.0f;
	join->pager.foreground = 3;
	if (!yt_hostile_menu_row(ship_fighters, deployed_fighters, row,
	    sizeof(row), &row_length)
	    || !normal_exit_line(join, NULL, 0U)
	    || !normal_exit_b05d(join, row, row_length, 0.0f)
	    || !normal_exit_b05d(join, prompt, sizeof(prompt) - 1U, 1.0f))
		return false;
	cycle->fresh_hostile_editor_entered = true;
	yt_pager_editor_enter(&join->pager, join->accumulator,
	    sizeof(join->accumulator));
	memcpy(join->accumulator, command, command_length);
	join->accumulator[command_length] = '\0';
	if (!main_buy_present_echo(&fixture->cycle.presentation, command,
	    command_length) || !normal_exit_line(join, NULL, 0U))
		return false;
	join->source[0] = '\r';
	join->source[1] = '\0';
	join->source_length = 1U;
	cycle->fresh_hostile_selected = command[0];
	return yt_hostile_menu_dispatch(join->accumulator)
	    == expected_route;
}

static bool
direct_emergency_warp_fresh_hostile_menu(
    struct hostile_mines_hazard_fixture *fixture,
    struct direct_warp_main_cycle_state *cycle)
{
	static const uint8_t command[] = "A";

	return direct_emergency_warp_fresh_hostile_menu_command(fixture, cycle,
	    command, sizeof(command) - 1U, YT_HOSTILE_MENU_ATTACK,
	    1000.0, 1250.0);
}

static bool
direct_emergency_warp_fresh_hostile_menu_carrier_failure(
    struct hostile_mines_hazard_fixture *fixture,
    struct direct_warp_main_cycle_state *cycle,
    enum direct_warp_hostile_menu_carrier_cut cut)
{
	static const uint8_t prompt[] =
	    "Option? (A,B,D,I,Q,S,T,W,?=Help):? ";
	struct viewer_pager_join *join;
	uint8_t row[96];
	size_t row_length;
	bool fighter_cut;
	bool before;

	if (fixture == NULL || cycle == NULL)
		return false;
	join = &fixture->cycle.presentation.viewer->join;
	fighter_cut = cut == DIRECT_WARP_HOSTILE_MENU_FIGHTER_BEFORE
	    || cut == DIRECT_WARP_HOSTILE_MENU_FIGHTER_AFTER;
	before = cut == DIRECT_WARP_HOSTILE_MENU_FIGHTER_BEFORE
	    || cut == DIRECT_WARP_HOSTILE_MENU_PROMPT_BEFORE;
	++cycle->fresh_hostile_player_reads;
	cycle->fresh_hostile_player_get_completed = true;
	cycle->final_field_record = 2;
	cycle->final_field_player = true;
	join->presentation.foreground = 3.0f;
	join->pager.foreground = 3;
	if (!yt_hostile_menu_row(1000.0, 1250.0, row, sizeof(row),
	    &row_length) || !normal_exit_line(join, NULL, 0U))
		return false;
	if (!fighter_cut && !normal_exit_b05d(join, row, row_length, 0.0f))
		return false;
	join->fail_at = join->event_count + (before ? 1U : 4U);
	if (normal_exit_b05d(join, fighter_cut ? row : prompt,
	    fighter_cut ? row_length : sizeof(prompt) - 1U,
	    fighter_cut ? 0.0f : 1.0f))
		return false;
	cycle->fresh_hostile_carrier_ended = true;
	return true;
}

struct direct_warp_hostile_menu_terminal_state {
	struct viewer_pager_join *join;
	bool running;
	bool terminated;
	bool closed;
};

static bool
direct_warp_hostile_menu_terminal_notice(void *context,
    const uint8_t *notice, size_t length)
{
	struct direct_warp_hostile_menu_terminal_state *terminal = context;

	return normal_exit_line(terminal->join, NULL, 0U)
	    && normal_exit_b05d(terminal->join, notice, length, 0.0f);
}

static bool
direct_warp_hostile_menu_terminal_close(void *context)
{
	struct direct_warp_hostile_menu_terminal_state *terminal = context;

	terminal->closed = true;
	return true;
}

static bool
direct_emergency_warp_fresh_hostile_menu_terminal(
    struct hostile_mines_hazard_fixture *fixture,
    struct direct_warp_main_cycle_state *cycle,
    enum yt_ab36_terminal_kind kind,
    struct direct_warp_hostile_menu_terminal_state *terminal)
{
	static const uint8_t prompt[] =
	    "Option? (A,B,D,I,Q,S,T,W,?=Help):? ";
	struct viewer_pager_join *join;
	uint8_t row[96];
	size_t row_length;

	if (fixture == NULL || cycle == NULL || terminal == NULL)
		return false;
	join = &fixture->cycle.presentation.viewer->join;
	++cycle->fresh_hostile_player_reads;
	cycle->fresh_hostile_player_get_completed = true;
	cycle->final_field_record = 2;
	cycle->final_field_player = true;
	join->presentation.foreground = 3.0f;
	join->pager.foreground = 3;
	if (!yt_hostile_menu_row(1000.0, 1250.0, row, sizeof(row),
	    &row_length) || !normal_exit_line(join, NULL, 0U)
	    || !normal_exit_b05d(join, row, row_length, 0.0f)
	    || !normal_exit_b05d(join, prompt, sizeof(prompt) - 1U, 1.0f))
		return false;
	cycle->fresh_hostile_editor_entered = true;
	yt_pager_editor_enter(&join->pager, join->accumulator,
	    sizeof(join->accumulator));
	memset(terminal, 0, sizeof(*terminal));
	terminal->join = join;
	terminal->running = true;
	return yt_input_ab36_terminal_run(kind, &terminal->running,
	    &terminal->terminated, direct_warp_hostile_menu_terminal_notice,
	    direct_warp_hostile_menu_terminal_close, terminal);
}

static bool
direct_emergency_warp_fresh_hostile_attack_admission_amount_with_ship(
    struct hostile_mines_hazard_fixture *fixture,
    struct direct_warp_main_cycle_state *cycle, const uint8_t *response,
    size_t response_length, float ship_fighters)
{
	static const uint8_t heading[] = "<Attack>";
	static const uint8_t prompt[] = "Attack with how many fighters? ";
	struct viewer_pager_join *join;
	struct qb_val_result parsed;
	uint8_t raw[4];

	if (fixture == NULL || cycle == NULL || response == NULL
	    || response_length == 0U
	    || response_length >= sizeof(fixture->cycle.presentation.viewer->join.accumulator)
	    || cycle->fresh_hostile_selected != 'A')
		return false;
	join = &fixture->cycle.presentation.viewer->join;
	cycle->fresh_hostile_attack_admission_entered = true;
	if (!normal_exit_b05d(join, heading, sizeof(heading) - 1U, 0.0f)
	    || !normal_exit_b05d(join, prompt, sizeof(prompt) - 1U, 1.0f))
		return false;
	yt_pager_editor_enter(&join->pager, join->accumulator,
	    sizeof(join->accumulator));
	memcpy(join->accumulator, response, response_length);
	join->accumulator[response_length] = '\0';
	if (!main_buy_present_echo(&fixture->cycle.presentation, response,
	    response_length) || !normal_exit_line(join, NULL, 0U))
		return false;
	join->source[0] = '\r';
	join->source[1] = '\0';
	join->source_length = 1U;
	parsed = qb_val(join->accumulator);
	if (!parsed.valid || parsed.overflow
	    || qb_mbf32_encode((float)parsed.value, raw) != QB_MBF_OK)
		return false;
	cycle->fresh_hostile_attack_commitment = qb_mbf32_decode(raw);
	if (yt_hostile_attack_admit(ship_fighters,
	    cycle->fresh_hostile_attack_commitment)
	    != YT_HOSTILE_ATTACK_ADMITTED)
		return false;
	cycle->fresh_hostile_attack_sector_get_boundary = true;
	return true;
}

static bool
direct_emergency_warp_fresh_hostile_attack_admission_amount(
    struct hostile_mines_hazard_fixture *fixture,
    struct direct_warp_main_cycle_state *cycle, const uint8_t *response,
    size_t response_length)
{
	return direct_emergency_warp_fresh_hostile_attack_admission_amount_with_ship(
	    fixture, cycle, response, response_length, 1000.0f);
}

static bool
direct_emergency_warp_fresh_hostile_attack_admission(
    struct hostile_mines_hazard_fixture *fixture,
    struct direct_warp_main_cycle_state *cycle)
{
	static const uint8_t response[] = "1";

	return direct_emergency_warp_fresh_hostile_attack_admission_amount_with_ship(
	    fixture, cycle, response, sizeof(response) - 1U, 1000.0f);
}

static bool
direct_emergency_warp_fresh_hostile_attack_sector_get_failure(
    struct direct_warp_main_cycle_state *cycle,
    enum direct_warp_gate_get_failure failure,
    struct direct_warp_gate_get_state *gate,
    struct yt_basic_fault_projection *projection,
    const struct yt_record *inherited_field)
{
	struct yt_record field;
	struct yt_error error;
	size_t accepted = 0U;
	size_t index;

	if (cycle == NULL || gate == NULL || projection == NULL
	    || inherited_field == NULL
	    || !cycle->fresh_hostile_attack_sector_get_boundary)
		return false;
	memset(gate, 0, sizeof(*gate));
	gate->database.file = tmpfile();
	if (gate->database.file == NULL)
		return false;
	gate->failure = failure;
	gate->accepted = failure == DIRECT_WARP_GATE_SEEK_52 ? 0U : 3U;
	gate->terminal_position = failure == DIRECT_WARP_GATE_SEEK_52
	    ? INT64_C(0x11223344) : INT64_C(0x55667788);
	gate->field = *inherited_field;
	gate->field_record = 2;
	gate->field_player = true;
	for (index = 0U; index < YT_RECORD_SIZE; ++index)
		gate->read_source.bytes[index] = (uint8_t)(index ^ 0x3cU);
	yt_database_set_seek_provider(&gate->database, direct_warp_gate_seek,
	    gate);
	yt_database_set_read_provider(&gate->database, direct_warp_gate_read,
	    gate);
	field = gate->field;
	++cycle->fresh_hostile_attack_sector_reads;
	yt_error_clear(&error);
	if (yt_database_random_get(&gate->database, 1054U, &field, &accepted,
	    &error)) {
		yt_database_close(&gate->database);
		return false;
	}
	if (gate->database.last_get.outcome == YT_DATABASE_GET_READ_ERROR) {
		gate->field = field;
		gate->field_record = 1054;
		gate->field_player = false;
		cycle->final_field_record = 1054;
		cycle->final_field_player = false;
	}
	if (!yt_error_attach_basic_fault_number(&error,
	    YT_BASIC_FAULT_HOSTILE_ATTACK_SECTOR_GET,
	    gate->database.last_get.basic_error)
	    || !yt_basic_fault_project(&error, NULL, 0U, NULL, 0U, NULL, 0U,
	    projection)) {
		yt_database_close(&gate->database);
		return false;
	}
	return true;
}

struct direct_warp_attack_entry_a41c_failure_state {
	struct direct_warp_gate_get_state io;
	struct yt_database_get_result sector_get;
	struct yt_database_get_result player_get;
	struct yt_record sector_source;
	struct yt_record sector_field;
	struct yt_record player_source;
	struct yt_record player_field;
	struct yt_player expected_player;
	float current_sector;
	struct yt_player_cache player_cache;
};

static bool
direct_emergency_warp_fresh_hostile_attack_entry_a41c_failure(
    struct hostile_mines_hazard_fixture *fixture,
    struct direct_warp_main_cycle_state *cycle,
    enum direct_warp_attack_sector_success sector_success,
    enum direct_warp_gate_get_failure player_failure,
    struct direct_warp_attack_entry_a41c_failure_state *entry,
    struct yt_basic_fault_projection *projection)
{
	struct direct_warp_gate_get_state *io;
	struct yt_current_player_hydration_state hydration;
	struct yt_player before;
	struct yt_record field;
	struct yt_error error;
	float current_sector = 1054.0f;
	float cloak_cache[4] = {-1.0f, -2.0f, 0.0f, -4.0f};
	size_t accepted = 0U;
	size_t index;

	if (fixture == NULL || cycle == NULL || entry == NULL
	    || projection == NULL
	    || !cycle->fresh_hostile_attack_sector_get_boundary)
		return false;
	memset(entry, 0, sizeof(*entry));
	io = &entry->io;
	io->database.file = tmpfile();
	if (io->database.file == NULL)
		return false;
	io->read_success = true;
	io->accepted = sector_success == DIRECT_WARP_ATTACK_SECTOR_FULL
	    ? YT_RECORD_SIZE : sector_success == DIRECT_WARP_ATTACK_SECTOR_SHORT
	    ? 3U : 0U;
	io->field = fixture->emergency_player.record;
	io->field_record = 2;
	io->field_player = true;
	for (index = 0U; index < YT_RECORD_SIZE; ++index)
		io->read_source.bytes[index] = (uint8_t)(index ^ 0x3cU);
	entry->sector_source = io->read_source;
	yt_database_set_seek_provider(&io->database, direct_warp_gate_seek, io);
	yt_database_set_read_provider(&io->database, direct_warp_gate_read, io);
	field = io->field;
	++cycle->fresh_hostile_attack_sector_reads;
	yt_error_clear(&error);
	if (!yt_database_random_get(&io->database, 1054U, &field, &accepted,
	    &error)) {
		yt_database_close(&io->database);
		return false;
	}
	entry->sector_get = io->database.last_get;
	entry->sector_field = field;
	io->field = field;
	io->field_record = 1054;
	io->field_player = false;
	cycle->final_field_record = 1054;
	cycle->final_field_player = false;
	memset(cycle->fresh_hostile_attack_surrender_latch_raw, 0,
	    sizeof(cycle->fresh_hostile_attack_surrender_latch_raw));

	io->read_success = false;
	io->failure = player_failure;
	io->accepted = player_failure == DIRECT_WARP_GATE_SEEK_52 ? 0U : 3U;
	io->terminal_position = player_failure == DIRECT_WARP_GATE_SEEK_52
	    ? INT64_C(0x11223344) : INT64_C(0x55667788);
	for (index = 0U; index < YT_RECORD_SIZE; ++index)
		io->read_source.bytes[index] = (uint8_t)(index ^ 0x5aU);
	before = fixture->emergency_player;
	memset(&hydration, 0, sizeof(hydration));
	hydration.player = &fixture->emergency_player;
	hydration.player_record = 2;
	hydration.current_sector_record = &current_sector;
	if (qb_mbf32_encode(51.0f, hydration.sector_record_offset_raw)
	    != QB_MBF_OK) {
		yt_database_close(&io->database);
		return false;
	}
	yt_error_clear(&error);
	if (yt_current_player_hydrate_run(&hydration,
	    direct_warp_gate_read_player, io, &error)
	    || !yt_basic_fault_project(&error, NULL, 0U, NULL, 0U, NULL, 0U,
	    projection) || memcmp(&fixture->emergency_player, &before,
	    sizeof(before)) != 0 || current_sector != 1054.0f
	    || memcmp(cloak_cache,
	    (const float[4]){-1.0f, -2.0f, 0.0f, -4.0f},
	    sizeof(cloak_cache)) != 0) {
		yt_database_close(&io->database);
		return false;
	}
	cycle->final_field_record = io->field_record;
	cycle->final_field_player = io->field_player;
	return true;
}

static bool
direct_emergency_warp_fresh_hostile_attack_opening_success(
    struct hostile_mines_hazard_fixture *fixture,
    struct direct_warp_main_cycle_state *cycle,
    enum direct_warp_attack_sector_success sector_success,
    enum direct_warp_attack_sector_success player_success,
    struct direct_warp_attack_entry_a41c_failure_state *entry)
{
	struct direct_warp_gate_get_state *io;
	struct viewer_pager_join *join;
	struct yt_current_player_hydration_state hydration;
	struct yt_present_result sound;
	struct yt_player before;
	struct yt_player fresh;
	struct yt_record field;
	struct yt_error error;
	size_t accepted = 0U;
	size_t index;

	if (fixture == NULL || cycle == NULL || entry == NULL
	    || !cycle->fresh_hostile_attack_sector_get_boundary)
		return false;
	memset(entry, 0, sizeof(*entry));
	io = &entry->io;
	join = &fixture->cycle.presentation.viewer->join;
	io->database.file = tmpfile();
	if (io->database.file == NULL)
		return false;
	io->read_success = true;
	io->accepted = sector_success == DIRECT_WARP_ATTACK_SECTOR_FULL
	    ? YT_RECORD_SIZE : sector_success == DIRECT_WARP_ATTACK_SECTOR_SHORT
	    ? 3U : 0U;
	io->field = fixture->emergency_player.record;
	io->field_record = 2;
	io->field_player = true;
	for (index = 0U; index < YT_RECORD_SIZE; ++index)
		io->read_source.bytes[index] = (uint8_t)(index ^ 0x3cU);
	entry->sector_source = io->read_source;
	yt_database_set_seek_provider(&io->database, direct_warp_gate_seek, io);
	yt_database_set_read_provider(&io->database, direct_warp_gate_read, io);
	field = io->field;
	++cycle->fresh_hostile_attack_sector_reads;
	yt_error_clear(&error);
	if (!yt_database_random_get(&io->database, 1054U, &field, &accepted,
	    &error)) {
		yt_database_close(&io->database);
		return false;
	}
	entry->sector_get = io->database.last_get;
	entry->sector_field = field;
	io->field = field;
	io->field_record = 1054;
	io->field_player = false;
	cycle->final_field_record = 1054;
	cycle->final_field_player = false;
	memset(cycle->fresh_hostile_attack_surrender_latch_raw, 0,
	    sizeof(cycle->fresh_hostile_attack_surrender_latch_raw));

	memset(&entry->player_source, 0xa5,
	    sizeof(entry->player_source));
	(void)yt_record_set_number(&entry->player_source, YT_F49, 21.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F53, 22.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F57, 1003.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F61, 23.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F65, 24.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F69, 25.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F73, 26.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F77, 27.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F81, 28.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F89, 29.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F93, 30.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F97, 31.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F109, 32.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F113, 33.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F117, 34.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F121, 35.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F125, 36.0f);
	(void)yt_record_set_number(&entry->player_source, YT_F129, 37.0f);
	io->read_source = entry->player_source;
	io->accepted = player_success == DIRECT_WARP_ATTACK_SECTOR_FULL
	    ? YT_RECORD_SIZE : player_success == DIRECT_WARP_ATTACK_SECTOR_SHORT
	    ? 3U : 0U;
	before = fixture->emergency_player;
	entry->current_sector = 1054.0f;
	entry->player_cache.cloak[0] = -1.0f;
	entry->player_cache.cloak[1] = -2.0f;
	entry->player_cache.cloak[2] = -3.0f;
	entry->player_cache.cloak[3] = -4.0f;
	memset(&hydration, 0, sizeof(hydration));
	hydration.player = &fixture->emergency_player;
	hydration.player_record = 2;
	hydration.current_sector_record = &entry->current_sector;
	hydration.player_cache = &entry->player_cache;
	if (qb_mbf32_encode(51.0f, hydration.sector_record_offset_raw)
	    != QB_MBF_OK) {
		yt_database_close(&io->database);
		return false;
	}
	++cycle->fresh_hostile_player_reads;
	yt_error_clear(&error);
	if (!yt_current_player_hydrate_run(&hydration,
	    direct_warp_gate_read_player, io, &error)) {
		yt_database_close(&io->database);
		return false;
	}
	entry->player_get = io->database.last_get;
	entry->player_field = io->field;
	yt_player_decode(&fresh, &entry->player_field);
	entry->expected_player = before;
	entry->expected_player.record = entry->player_field;
	entry->expected_player.sector = fresh.sector;
	entry->expected_player.fighters = fresh.fighters;
	entry->expected_player.turns = fresh.turns;
	entry->expected_player.credits = fresh.credits;
	entry->expected_player.danger_scanner = fresh.danger_scanner;
	entry->expected_player.missiles = fresh.missiles;
	entry->expected_player.mines = fresh.mines;
	entry->expected_player.team = fresh.team;
	entry->expected_player.holds = fresh.holds;
	entry->expected_player.ore = fresh.ore;
	entry->expected_player.organics = fresh.organics;
	entry->expected_player.equipment = fresh.equipment;
	entry->expected_player.plasma = fresh.plasma;
	entry->expected_player.score = fresh.score;
	entry->expected_player.ports_owned = fresh.ports_owned;
	entry->expected_player.ground_forces = fresh.ground_forces;
	entry->expected_player.cloak = fresh.cloak;
	entry->expected_player.shields = fresh.shields;
	if (memcmp(&fixture->emergency_player, &entry->expected_player,
	    sizeof(entry->expected_player)) != 0
	    || qb_mbf32_encode(2.0f,
	    cycle->fresh_hostile_attack_sound_selector_raw) != QB_MBF_OK
	    || yt_present_sound(2.0f, &join->presentation, &sound)
	    != YT_PRESENT_OK) {
		yt_database_close(&io->database);
		return false;
	}
	++cycle->fresh_hostile_attack_opening_sound_calls;
	for (index = 0U; index < sound.event_count; ++index) {
		if (sound.events[index].operation == YT_PRESENT_LOCAL_PLAY) {
			++cycle->fresh_hostile_attack_opening_play_events;
			cycle->fresh_hostile_attack_opening_play_length
			    += sound.events[index].length;
		}
	}
	viewer_pager_capture_result(join, &sound);
	cycle->fresh_hostile_attack_first_checkpoint = true;
	cycle->final_field_record = io->field_record;
	cycle->final_field_player = io->field_player;
	return true;
}

