static bool
direct_warp_attack_combat_spill(void *context, double *fighters,
    float *shields, struct yt_error *error)
{
	struct direct_warp_attack_combat_join *join = context;
	const struct yt_fighter_shield_spill_ops ops = {
		direct_warp_attack_combat_random,
		direct_warp_attack_spill_present,
		direct_warp_attack_spill_store,
	};
	bool result;

	if (!join->allow_spill) {
		join->unexpected_spill = true;
		return false;
	}
	++join->spill_calls;
	join->spill = (struct yt_fighter_shield_spill_state){
		.fighters = *fighters,
		.shields = *shields,
	};
	result = yt_fighter_shield_spill_run(&join->spill, &ops, join, error);
	*fighters = join->spill.fighters;
	*shields = join->spill.shields;
	return result;
}

static bool
direct_warp_attack_persistence_read_player(void *context, int player_record,
    struct yt_player *player, struct yt_error *error)
{
	struct direct_warp_attack_combat_join *join = context;

	(void)error;
	if (player_record != 2 || player == NULL)
		return false;
	++join->persistence_player_reads;
	if (join->persistence_player_reads
	    == join->fail_persistence_player_read_at)
		return false;
	if (join->persistence_player_reads == 1U)
		*player = join->persistence_player;
	else if (join->persistence_player_reads == 2U)
		return direct_warp_attack_combat_read_player(context,
		    player_record, player, error);
	else
		return false;
	join->cycle->final_field_record = 2;
	join->cycle->final_field_player = true;
	return true;
}

