static void
test_hostile_bribe_fatal_prefix_cuts(void)
{
	enum fatal_cut {
		FATAL_CUT_FIRST_CARRIER,
		FATAL_CUT_SECOND_CARRIER,
		FATAL_CUT_COMMON_PLAYER_GET,
		FATAL_CUT_SOUND,
		FATAL_CUT_DEATH_PLAYER_GET,
		FATAL_CUT_DEATH_PLAYER_PUT,
		FATAL_CUT_FIRST_SECTOR_GET,
		FATAL_CUT_SECTOR_PUT,
		FATAL_CUT_POST_PUT_SECTOR_GET,
		FATAL_CUT_TEAM_REMOVE,
		FATAL_CUT_NEWS,
		FATAL_CUT_FLUSH,
		FATAL_CUT_WAIT,
		FATAL_CUT_COUNT,
	};
	static const uint8_t name[] = "Ada";
	static const uint8_t expected_news[] = "  -  Ada was killed!\r\n";
	static const struct {
		size_t length;
		uint64_t hash;
		size_t colors;
		uint64_t color_hash;
		size_t fragment;
		size_t events;
		size_t samples;
	} expected[3][3] = {
		{{101U, UINT64_C(0xc6a3b4b024774f47), 3U,
		 UINT64_C(0x2207a27a6260aaca), 0U, 16U, 3U},
		 {130U, UINT64_C(0xa6452caa9d483a7a), 3U,
		 UINT64_C(0x2207a27a6260aaca), 29U, 19U, 4U},
		 {132U, UINT64_C(0xc79d585ab142c207), 4U,
		 UINT64_C(0x01b4fd96ce8921d5), 0U, 20U, 4U}},
		{{135U, UINT64_C(0x595b51c018d9c386), 10U,
		 UINT64_C(0x9c1b09fb228baecc), 0U, 16U, 3U},
		 {178U, UINT64_C(0x046937c9ffb91eca), 11U,
		 UINT64_C(0xc24239f1c20735a2), 29U, 19U, 4U},
		 {180U, UINT64_C(0x8f66998d586a42d7), 12U,
		 UINT64_C(0xca2ee8d2e302e66d), 0U, 20U, 4U}},
		{{0U, UINT64_C(0xcbf29ce484222325), 3U,
		 UINT64_C(0x2207a27a6260aaca), 0U, 16U, 3U},
		 {0U, UINT64_C(0xcbf29ce484222325), 3U,
		 UINT64_C(0x2207a27a6260aaca), 29U, 19U, 4U},
		 {0U, UINT64_C(0xcbf29ce484222325), 4U,
		 UINT64_C(0x01b4fd96ce8921d5), 0U, 20U, 4U}},
	};
	struct physical_viewer_join viewer;
	struct yt_file_viewer_stream_state stream;
	struct hostile_mines_hazard_fixture fixture;
	struct direct_warp_main_cycle_state cycle;
	struct direct_warp_bribe_attack_join joined;
	struct hostile_bribe_fatal_cycle_join fatal;
	struct yt_hostile_bribe_state bribe;
	struct yt_record record;
	struct yt_error error;
	uint8_t expected_record[4];
	uint8_t remote[256];
	size_t endpoint;
	size_t cut;
	size_t terminal;

	CHECK(qb_mbf32_encode(2.0f, expected_record) == QB_MBF_OK);
	for (endpoint = 0U; endpoint < 3U; ++endpoint) {
		for (cut = 0U; cut < FATAL_CUT_COUNT; ++cut) {
			terminal = cut < 2U ? cut : 2U;
			memset(&viewer, 0, sizeof(viewer));
			fixture_viewer_initialize(&viewer, &stream,
			    retained_scoreboard, sizeof(retained_scoreboard) - 1U,
			    "YTSCORE.ASC", endpoint == 1U, remote, sizeof(remote));
			if (endpoint == 2U)
				viewer.join.presentation.sound.mode = 1.0f;
			viewer.join.presentation.sound.user_sound = 0.0f;
			memset(&fixture, 0, sizeof(fixture));
			fixture.cycle.presentation.viewer = &viewer;
			fixture.draws[0] = 81143.0f / 8388608.0f;
			fixture.draws[1] = 4221177.0f / 16777216.0f;
			memset(&cycle, 0, sizeof(cycle));
			CHECK(direct_emergency_warp_fresh_hostile_menu_command(
			    &fixture, &cycle, (const uint8_t *)"B", 1U,
			    YT_HOSTILE_MENU_BRIBE, 0.0, 10.0));

			memset(&fatal, 0, sizeof(fatal));
			fatal.viewer = &viewer;
			fatal.stream = &stream;
			if (cut < FATAL_CUT_COMMON_PLAYER_GET)
				fatal.attention_carrier_cut = (int)cut + 1;
			else if (cut == FATAL_CUT_COMMON_PLAYER_GET)
				fatal.fail_player_read_at = 1U;
			else if (cut == FATAL_CUT_SOUND)
				fatal.fail_sound = true;
			else if (cut == FATAL_CUT_DEATH_PLAYER_GET)
				fatal.fail_player_read_at = 2U;
			else if (cut == FATAL_CUT_DEATH_PLAYER_PUT)
				fatal.fail_player_write_at = 1U;
			else if (cut == FATAL_CUT_FIRST_SECTOR_GET)
				fatal.fail_sector_read_at = 1U;
			else if (cut == FATAL_CUT_SECTOR_PUT)
				fatal.fail_sector_write_at = 1U;
			else if (cut == FATAL_CUT_POST_PUT_SECTOR_GET)
				fatal.fail_sector_read_at = 734U;
			else if (cut == FATAL_CUT_TEAM_REMOVE)
				fatal.fail_team_removal = true;
			else if (cut == FATAL_CUT_NEWS)
				fatal.fail_news = true;
			else if (cut == FATAL_CUT_FLUSH)
				fatal.fail_flush = true;
			else if (cut == FATAL_CUT_WAIT)
				fatal.fail_wait = true;
			memset(&record, 0, sizeof(record));
			yt_record_set_text(&record, name, sizeof(name) - 1U);
			(void)yt_record_set_number(&record, YT_F49, 20.0f);
			(void)yt_record_set_number(&record, YT_F57, 733.0f);
			(void)yt_record_set_number(&record, YT_F81, 100.0f);
			(void)yt_record_set_number(&record, YT_F85,
			    (float)(sizeof(name) - 1U));
			(void)yt_record_set_number(&record, YT_F93, 1.0f);
			(void)yt_record_set_number(&record, YT_F125, 0.5f);
			yt_player_decode(&fatal.player, &record);
			yt_record_blank(&record);
			(void)yt_record_set_number(&record, YT_F81, 10.0f);
			(void)yt_record_set_number(&record, YT_F85, 2.0f);
			yt_sector_decode(&fatal.sector, &record);

			memset(&joined, 0, sizeof(joined));
			joined.fixture = &fixture;
			joined.cycle = &cycle;
			joined.fatal_handler = hostile_bribe_fatal_run;
			joined.fatal_handler_context = &fatal;
			memset(&bribe, 0, sizeof(bribe));
			bribe.current_player_record = 2;
			bribe.current_sector = 733;
			bribe.owner = -2.0f;
			bribe.cached_defenders = 10.0;
			bribe.ship_fighters = 0.0;
			bribe.shields = 0.0f;
			bribe.credits = 100.0;
			bribe.real_first_name = name;
			bribe.real_first_name_length = sizeof(name) - 1U;
			yt_error_clear(&error);
			CHECK(!yt_hostile_bribe_run(&bribe,
			    &direct_warp_bribe_attack_ops, &joined, &error));

			CHECK(bribe.route == YT_HOSTILE_BRIBE_FATAL
			    && bribe.branch == YT_HOSTILE_BRIBE_LIFE_DEMAND
			    && bribe.draws_consumed == 2U
			    && bribe.fatal_called
			    && !bribe.complete && !bribe.combat_called
			    && joined.random_calls == 2U
			    && joined.fatal_calls == 1U
			    && fatal.fatal_start
			    == (endpoint == 0U ? 99U : endpoint == 1U ? 123U : 0U)
			    && fatal.fatal.foreground == 3.0f
			    && fatal.fatal.pager_foreground == 3
			    && fatal.fatal.field_valid == (cut >= FATAL_CUT_SOUND)
			    && !fatal.fatal.wait_complete
			    && !fatal.fatal.normal_exit
			    && fatal.player_reads == (cut < 2U ? 0U
			    : cut <= FATAL_CUT_SOUND ? 1U : 2U)
			    && fatal.player_writes
			    == (cut >= FATAL_CUT_DEATH_PLAYER_PUT ? 1U : 0U)
			    && fatal.sector_reads
			    == (cut < FATAL_CUT_FIRST_SECTOR_GET ? 0U
			    : cut == FATAL_CUT_FIRST_SECTOR_GET ? 1U
			    : cut == FATAL_CUT_SECTOR_PUT ? 733U
			    : cut == FATAL_CUT_POST_PUT_SECTOR_GET ? 734U : 2004U)
			    && fatal.sector_writes
			    == (cut >= FATAL_CUT_SECTOR_PUT ? 1U : 0U)
			    && fatal.sound_calls == (cut >= FATAL_CUT_SOUND ? 1U : 0U)
			    && fatal.death_calls
			    == (cut >= FATAL_CUT_DEATH_PLAYER_GET ? 1U : 0U)
			    && fatal.wait_calls == (cut == FATAL_CUT_WAIT ? 1U : 0U)
			    && fatal.team_removals
			    == (cut >= FATAL_CUT_TEAM_REMOVE ? 1U : 0U)
			    && fatal.news_calls == (cut >= FATAL_CUT_NEWS ? 1U : 0U)
			    && fatal.flushes == (cut >= FATAL_CUT_FLUSH ? 1U : 0U)
			    && fatal.current_player_set == (cut >= FATAL_CUT_FLUSH)
			    && fatal.death.complete == (cut == FATAL_CUT_WAIT)
			    && fatal.news_length
			    == (cut >= FATAL_CUT_FLUSH
			    ? sizeof(expected_news) - 1U : 0U)
			    && (cut < FATAL_CUT_FLUSH || memcmp(fatal.news, expected_news,
			    sizeof(expected_news) - 1U) == 0)
			    && (cut < FATAL_CUT_SOUND || fatal.selector == 3.0f)
			    && (cut < FATAL_CUT_DEATH_PLAYER_GET
			    || memcmp(fatal.active_cache_raw,
			    (const uint8_t[]){0x00U, 0x00U, 0x7aU, 0x00U}, 4U)
			    == 0)
			    && (cut != FATAL_CUT_WAIT || fatal.duration == 5.0f)
			    && fatal.player.killed_by
			    == (cut > FATAL_CUT_DEATH_PLAYER_PUT ? 2.0f : 0.0f)
			    && fatal.player.sector
			    == (cut > FATAL_CUT_DEATH_PLAYER_PUT ? 0.0f : 733.0f)
			    && fatal.sector.fighter_owner
			    == (cut > FATAL_CUT_SECTOR_PUT ? -2.0f : 2.0f)
			    && fatal.sector.fighters == 10.0f
			    && (cut <= FATAL_CUT_DEATH_PLAYER_PUT
			    || fatal.written_player.killed_by == 2.0f)
			    && (cut <= FATAL_CUT_SECTOR_PUT
			    || fatal.written_sector.fighter_owner == -2.0f)
			    && fixture.draw_position == 2U);
			CHECK(viewer.join.remote_length
			    == expected[endpoint][terminal].length
			    && viewer_bytes_fnv1a64(remote,
			    viewer.join.remote_length)
			    == expected[endpoint][terminal].hash);
			CHECK(viewer.join.local_row_count
			    == (cut < 2U ? 6U : 7U)
			    && viewer_rows_fnv1a64(&viewer.join)
			    == (cut < 2U ? UINT64_C(0xb98806a4c3918dd8)
			    : UINT64_C(0xf776bd8f05a26c98))
			    && viewer.join.local_color_count
			    == expected[endpoint][terminal].colors
			    && viewer_colors_fnv1a64(&viewer.join)
			    == expected[endpoint][terminal].color_hash
			    && viewer.join.local_fragment_length
			    == expected[endpoint][terminal].fragment
			    && viewer_bytes_fnv1a64(viewer.join.local_fragment,
			    viewer.join.local_fragment_length)
			    == (cut == 1U ? UINT64_C(0xb123cceada0ab000)
			    : UINT64_C(0xcbf29ce484222325))
			    && viewer.join.event_count
			    == expected[endpoint][terminal].events
			    && viewer.join.sample_calls
			    == expected[endpoint][terminal].samples);
			yt_text_input_destroy(&viewer.input);
		}
	}
}

static void
test_direct_emergency_warp_hostile_attack_fatal_cycle(void)
{
	static const uint8_t current_name[] = "STATIC PILOT";
	static const uint8_t expected_news[] =
	    "  -  STATIC PILOT was killed!\r\n";
	static const uint8_t time_text[] = " 14:59  ";
	static const struct {
		bool main;
		bool ansi;
		const uint8_t *command;
		size_t command_length;
		size_t prefix_length;
		size_t suffix_length;
		uint64_t suffix_hash;
		size_t local_rows;
		uint64_t local_row_hash;
		size_t local_colors;
		uint64_t local_color_hash;
	} callers[] = {
		{true, false, (const uint8_t *)"W", 1U, 912U, 1477U,
		 UINT64_C(0xea0d1d2d7ccdceeb), 86U,
		 UINT64_C(0x646426a6deae9e98), 34U,
		 UINT64_C(0x05c809b06029fd3d)},
		{true, true, (const uint8_t *)"W", 1U, 1184U, 1621U,
		 UINT64_C(0x42dafd72c74a1f97), 86U,
		 UINT64_C(0x646426a6deae9e98), 156U,
		 UINT64_C(0xb8a9d51bc9b3d672)},
		{false, false, (const uint8_t *)"W", 1U, 934U, 1477U,
		 UINT64_C(0xea0d1d2d7ccdceeb), 87U,
		 UINT64_C(0x9fdde4eff2202cbd), 35U,
		 UINT64_C(0x1394ced89cb7fc4a)},
		{false, false, (const uint8_t *)"WT", 2U, 935U, 1477U,
		 UINT64_C(0xea0d1d2d7ccdceeb), 87U,
		 UINT64_C(0x0827ead298860cf4), 35U,
		 UINT64_C(0x1394ced89cb7fc4a)},
		{false, true, (const uint8_t *)"W", 1U, 1216U, 1621U,
		 UINT64_C(0x42dafd72c74a1f97), 87U,
		 UINT64_C(0x9fdde4eff2202cbd), 158U,
		 UINT64_C(0x12fab641cbed07ad)},
		{false, true, (const uint8_t *)"WT", 2U, 1217U, 1621U,
		 UINT64_C(0x42dafd72c74a1f97), 87U,
		 UINT64_C(0x0827ead298860cf4), 158U,
		 UINT64_C(0x12fab641cbed07ad)},
	};
	struct physical_viewer_join viewer;
	struct yt_file_viewer_stream_state stream;
	struct hostile_mines_hazard_fixture fixture;
	struct direct_warp_main_cycle_state cycle;
	struct direct_warp_attack_combat_join attack;
	struct hostile_bribe_fatal_cycle_join fatal;
	struct hostile_attack_fatal_cycle_join bridge;
	struct yt_hostile_attack_combat_state combat;
	struct normal_exit_info_values info;
	struct yt_record record;
	struct yt_error error;
	uint8_t expected_record[4];
	uint8_t remote[4000];
	size_t ends[3];
	size_t caller;
	size_t suffix_length;

	CHECK(qb_mbf32_encode(2.0f, expected_record) == QB_MBF_OK);
	for (caller = 0U; caller < YT_ARRAY_LEN(callers); ++caller) {
		memset(&viewer, 0, sizeof(viewer));
		fixture_viewer_initialize(&viewer, &stream, retained_scoreboard,
		    sizeof(retained_scoreboard) - 1U, "YTSCORE.ASC",
		    callers[caller].ansi, remote, sizeof(remote));
		viewer.join.presentation.sound.user_sound = 0.0f;
		memset(&fixture, 0, sizeof(fixture));
		fixture.cycle.presentation.viewer = &viewer;
		fixture.emergency_sector_cache = 733.0f;
		fixture.draws[0] = 0.0f;
		fixture.draws[1] = 0.0f;
		fixture.draws[2] = 0.75f;
		fixture.draws[3] = 0.5f;
		fixture.draws[4] = 0.949999988079071f;
		fixture.draws[5] = 0.999f;
		fixture.draws[6] = 0.9f;
		fixture.draws[7] = 0.0f;
		fixture.draws[8] = 0.0f;
		memset(&record, 0xa5, sizeof(record));
		(void)yt_record_set_number(&record, YT_F49, 17.0f);
		(void)yt_record_set_number(&record, YT_F57, 733.0f);
		yt_player_decode(&fixture.emergency_player, &record);
		fixture.hazard_player = fixture.emergency_player;
		if (callers[caller].main) {
			CHECK(direct_emergency_warp_main_hostile_handoff_run(
			    &fixture, callers[caller].ansi, &cycle, ends));
		}
		else {
			CHECK(direct_emergency_warp_hostile_cycle_run(
			    &fixture, callers[caller].ansi, callers[caller].command,
			    callers[caller].command_length, DIRECT_WARP_HOSTILE_DEFENSE,
			    &cycle, ends));
		}
		CHECK(direct_emergency_warp_fresh_hostile_menu_command(&fixture,
		    &cycle, (const uint8_t *)"A", 1U, YT_HOSTILE_MENU_ATTACK,
		    1.0, 2.0)
		    && direct_emergency_warp_fresh_hostile_attack_admission(
		    &fixture, &cycle));
		CHECK(viewer.join.remote_length == callers[caller].prefix_length);

		memset(&attack, 0, sizeof(attack));
		attack.fixture = &fixture;
		attack.cycle = &cycle;
		attack.current_sector_record = 1054.0f;
		attack.sector_record_offset = 51.0f;
		attack.allow_spill = true;
		memset(&record, 0x3c, sizeof(record));
		(void)yt_record_set_number(&record, YT_F81, 2.0f);
		(void)yt_record_set_number(&record, YT_F85, 2.0f);
		yt_sector_decode(&attack.entry_sector, &record);
		memset(&record, 0xa5, sizeof(record));
		yt_record_set_text(&record, current_name,
		    sizeof(current_name) - 1U);
		(void)yt_record_set_number(&record, YT_F49, 17.0f);
		(void)yt_record_set_number(&record, YT_F53, 1.0f);
		(void)yt_record_set_number(&record, YT_F57, 1003.0f);
		(void)yt_record_set_number(&record, YT_F61, 1.0f);
		(void)yt_record_set_number(&record, YT_F125, 0.0f);
		yt_player_decode(&attack.attack_player, &record);
		memset(&record, 0x5a, sizeof(record));
		yt_record_set_text(&record, (const uint8_t *)"FRESH PLAYER", 12U);
		(void)yt_record_set_number(&record, YT_F49, 17.0f);
		(void)yt_record_set_number(&record, YT_F53, 9.0f);
		(void)yt_record_set_number(&record, YT_F57, 1003.0f);
		(void)yt_record_set_number(&record, YT_F61, 9.0f);
		(void)yt_record_set_number(&record, YT_F117, 0.0f);
		yt_player_decode(&attack.persistence_player, &record);
		memset(&record, 0x96, sizeof(record));
		(void)yt_record_set_number(&record, YT_F81, 2.0f);
		(void)yt_record_set_number(&record, YT_F85, 2.0f);
		yt_sector_decode(&attack.persistence_sector, &record);

		memset(&fatal, 0, sizeof(fatal));
		fatal.viewer = &viewer;
		fatal.stream = &stream;
		fatal.current_name = current_name;
		fatal.current_name_length = sizeof(current_name) - 1U;
		fatal.owned_sector = 1003;
		bridge = (struct hostile_attack_fatal_cycle_join){&attack, &fatal};
		attack.fatal_handler = hostile_attack_fatal_cycle_run;
		attack.fatal_handler_context = &bridge;
		combat = (struct yt_hostile_attack_combat_state){
			.current_player_record = 2,
			.current_sector = 1003,
			.commitment = 1.0,
			.allow_surrender = false,
			.cached_defenders = 2.0,
			.sector = attack.entry_sector,
			.cached_player_name = current_name,
			.cached_player_name_length = sizeof(current_name) - 1U,
			.real_first_name = (const uint8_t *)"Sysop",
			.real_first_name_length = 5U,
			.owner_label = (const uint8_t *)"Ordinary",
			.owner_label_length = 8U,
			.turns_per_day = 500.0f,
			.headquarters = 1.0f,
		};
		yt_error_clear(&error);
		CHECK(yt_hostile_attack_combat_run(&combat,
		    &direct_warp_attack_combat_ops, &attack, &error));
		memset(&info, 0, sizeof(info));
		info.player = fatal.player;
		info.cached_name = current_name;
		info.cached_name_length = sizeof(current_name) - 1U;
		CHECK(normal_exit_body_run_info(&viewer, &stream, false,
		    time_text, sizeof(time_text) - 1U, 15.0f, &info,
		    &fatal.normal_exit));

		CHECK(combat.complete
		    && combat.route == YT_HOSTILE_ATTACK_COMBAT_FATAL
		    && combat.attacker_loss == 1.0 && combat.defender_loss == 0.0
		    && combat.ship_fighters == 0.0
		    && combat.deployed_remaining == 2.0
		    && combat.current.shields == 0.0f && combat.iterations == 1U
		    && combat.spill_called && attack.spill.complete
		    && combat.persistence.complete
		    && combat.persistence.route == YT_HOSTILE_ATTACK_PERSISTENCE_FATAL
		    && attack.random_calls == 2U && attack.spill_calls == 1U
		    && attack.spill_stores == 1U
		    && attack.spill.fighters == 2.0
		    && attack.spill.shields == 0.0f
		    && attack.persistence_player_reads == 1U
		    && attack.persistence_player_writes == 1U
		    && attack.persistence_sector_reads == 1U
		    && attack.persistence_sector_writes == 1U
		    && attack.persistence_blanks == 0U
		    && !attack.unexpected_spill && !attack.unexpected_fatal
		    && !attack.unexpected_tail_effect);
		CHECK(attack.written_player.fighters == 0.0f
		    && attack.written_player.shields == 0.0f
		    && attack.written_sector.fighters == 2.0f
		    && attack.written_sector.fighter_owner == 2.0f
		    && fatal.fatal.wait_complete && fatal.fatal.normal_exit
		    && fatal.death.complete && fatal.player.killed_by == 2.0f
		    && fatal.player.sector == 0.0f
		    && fatal.written_sector.fighter_owner == -2.0f
		    && fatal.news_length == sizeof(expected_news) - 1U
		    && memcmp(fatal.news, expected_news,
		    sizeof(expected_news) - 1U) == 0
		    && fixture.draw_position == 9U);
		suffix_length = viewer.join.remote_length
		    - callers[caller].prefix_length;
		CHECK(suffix_length == callers[caller].suffix_length
		    && viewer_bytes_fnv1a64(
		    remote + callers[caller].prefix_length, suffix_length)
		    == callers[caller].suffix_hash
		    && viewer.join.local_row_count == callers[caller].local_rows
		    && viewer_rows_fnv1a64(&viewer.join)
		    == callers[caller].local_row_hash
		    && viewer.join.local_color_count == callers[caller].local_colors
		    && viewer_colors_fnv1a64(&viewer.join)
		    == callers[caller].local_color_hash
		    && viewer.join.local_fragment_length == 0U);
		yt_text_input_destroy(&viewer.input);
	}
}

enum direct_warp_attack_fatal_prefix_cut {
	DIRECT_WARP_ATTACK_FATAL_SPILL_RANDOM = 0,
	DIRECT_WARP_ATTACK_FATAL_SPILL_FIGHTER_ROW,
	DIRECT_WARP_ATTACK_FATAL_SPILL_SHIELD_ROW,
	DIRECT_WARP_ATTACK_FATAL_PLAYER_GET,
	DIRECT_WARP_ATTACK_FATAL_PLAYER_PUT,
	DIRECT_WARP_ATTACK_FATAL_SECTOR_GET,
	DIRECT_WARP_ATTACK_FATAL_SECTOR_PUT,
};

static bool
direct_warp_attack_fatal_prefix_setup(struct physical_viewer_join *viewer,
    struct yt_file_viewer_stream_state *stream,
    struct hostile_mines_hazard_fixture *fixture,
    struct direct_warp_main_cycle_state *cycle,
    struct direct_warp_attack_combat_join *attack,
    struct yt_hostile_attack_combat_state *combat, bool main, bool ansi,
    const uint8_t *command, size_t command_length, uint8_t *remote,
    size_t remote_capacity, size_t ends[3])
{
	static const uint8_t current_name[] = "STATIC PILOT";
	struct yt_record record;

	memset(viewer, 0, sizeof(*viewer));
	fixture_viewer_initialize(viewer, stream, retained_scoreboard,
	    sizeof(retained_scoreboard) - 1U, "YTSCORE.ASC", ansi, remote,
	    remote_capacity);
	viewer->join.presentation.sound.user_sound = 0.0f;
	memset(fixture, 0, sizeof(*fixture));
	fixture->cycle.presentation.viewer = viewer;
	fixture->emergency_sector_cache = 733.0f;
	fixture->draws[0] = 0.0f;
	fixture->draws[1] = 0.0f;
	fixture->draws[2] = 0.75f;
	fixture->draws[3] = 0.5f;
	fixture->draws[4] = 0.949999988079071f;
	fixture->draws[5] = 0.999f;
	fixture->draws[6] = 0.9f;
	fixture->draws[7] = 0.0f;
	fixture->draws[8] = 0.0f;
	memset(&record, 0xa5, sizeof(record));
	(void)yt_record_set_number(&record, YT_F49, 17.0f);
	(void)yt_record_set_number(&record, YT_F57, 733.0f);
	yt_player_decode(&fixture->emergency_player, &record);
	fixture->hazard_player = fixture->emergency_player;
	if (main) {
		if (!direct_emergency_warp_main_hostile_handoff_run(fixture,
		    ansi, cycle, ends))
			return false;
	} else if (!direct_emergency_warp_hostile_cycle_run(fixture, ansi,
	    command, command_length, DIRECT_WARP_HOSTILE_DEFENSE, cycle, ends))
		return false;
	if (!direct_emergency_warp_fresh_hostile_menu_command(fixture, cycle,
	    (const uint8_t *)"A", 1U, YT_HOSTILE_MENU_ATTACK, 1.0, 2.0)
	    || !direct_emergency_warp_fresh_hostile_attack_admission(fixture,
	    cycle))
		return false;

	memset(attack, 0, sizeof(*attack));
	attack->fixture = fixture;
	attack->cycle = cycle;
	attack->current_sector_record = 1054.0f;
	attack->sector_record_offset = 51.0f;
	attack->allow_spill = true;
	memset(&record, 0x3c, sizeof(record));
	(void)yt_record_set_number(&record, YT_F81, 2.0f);
	(void)yt_record_set_number(&record, YT_F85, 2.0f);
	yt_sector_decode(&attack->entry_sector, &record);
	memset(&record, 0xa5, sizeof(record));
	yt_record_set_text(&record, current_name, sizeof(current_name) - 1U);
	(void)yt_record_set_number(&record, YT_F49, 17.0f);
	(void)yt_record_set_number(&record, YT_F53, 1.0f);
	(void)yt_record_set_number(&record, YT_F57, 1003.0f);
	(void)yt_record_set_number(&record, YT_F61, 1.0f);
	(void)yt_record_set_number(&record, YT_F125, 0.0f);
	yt_player_decode(&attack->attack_player, &record);
	memset(&record, 0x5a, sizeof(record));
	yt_record_set_text(&record, (const uint8_t *)"FRESH PLAYER", 12U);
	(void)yt_record_set_number(&record, YT_F49, 17.0f);
	(void)yt_record_set_number(&record, YT_F53, 9.0f);
	(void)yt_record_set_number(&record, YT_F57, 1003.0f);
	(void)yt_record_set_number(&record, YT_F61, 9.0f);
	(void)yt_record_set_number(&record, YT_F117, 0.0f);
	yt_player_decode(&attack->persistence_player, &record);
	memset(&record, 0x96, sizeof(record));
	(void)yt_record_set_number(&record, YT_F81, 2.0f);
	(void)yt_record_set_number(&record, YT_F85, 2.0f);
	yt_sector_decode(&attack->persistence_sector, &record);
	*combat = (struct yt_hostile_attack_combat_state){
		.current_player_record = 2,
		.current_sector = 1003,
		.commitment = 1.0,
		.allow_surrender = false,
		.cached_defenders = 2.0,
		.sector = attack->entry_sector,
		.cached_player_name = current_name,
		.cached_player_name_length = sizeof(current_name) - 1U,
		.real_first_name = (const uint8_t *)"Sysop",
		.real_first_name_length = 5U,
		.owner_label = (const uint8_t *)"Ordinary",
		.owner_label_length = 8U,
		.turns_per_day = 500.0f,
		.headquarters = 1.0f,
	};
	return true;
}

static void
test_direct_emergency_warp_hostile_attack_fatal_prefixes(void)
{
	static const struct {
		bool main;
		bool ansi;
		const uint8_t *command;
		size_t command_length;
		size_t prefix_length;
		size_t failure_rows;
		size_t failure_colors;
	} callers[] = {
		{true, false, (const uint8_t *)"W", 1U, 912U, 39U, 11U},
		{true, true, (const uint8_t *)"W", 1U, 1184U, 39U, 61U},
		{false, false, (const uint8_t *)"W", 1U, 934U, 40U, 12U},
		{false, false, (const uint8_t *)"WT", 2U, 935U, 40U, 12U},
		{false, true, (const uint8_t *)"W", 1U, 1216U, 40U, 63U},
		{false, true, (const uint8_t *)"WT", 2U, 1217U, 40U, 63U},
	};
	static const struct {
		size_t length[2];
		uint64_t hash[2];
	} expected[] = {
		{{107U, 131U}, {UINT64_C(0x2da512af1d09868e),
		    UINT64_C(0x713c79d05e034b0c)}},
		{{107U, 131U}, {UINT64_C(0x2da512af1d09868e),
		    UINT64_C(0x713c79d05e034b0c)}},
		{{130U, 154U}, {UINT64_C(0xa705852c4b3966d7),
		    UINT64_C(0x7e96bb8d7e06b695)}},
		{{153U, 177U}, {UINT64_C(0xa1b2a9d76fa1766b),
		    UINT64_C(0x2a571177a3c3e6d9)}},
		{{153U, 177U}, {UINT64_C(0xa1b2a9d76fa1766b),
		    UINT64_C(0x2a571177a3c3e6d9)}},
		{{153U, 177U}, {UINT64_C(0xa1b2a9d76fa1766b),
		    UINT64_C(0x2a571177a3c3e6d9)}},
		{{153U, 177U}, {UINT64_C(0xa1b2a9d76fa1766b),
		    UINT64_C(0x2a571177a3c3e6d9)}},
	};
	struct physical_viewer_join viewer;
	struct yt_file_viewer_stream_state stream;
	struct hostile_mines_hazard_fixture fixture;
	struct direct_warp_main_cycle_state cycle;
	struct direct_warp_attack_combat_join attack;
	struct yt_hostile_attack_combat_state combat;
	struct yt_error error;
	uint8_t remote[1800];
	size_t ends[3];
	size_t caller;
	size_t cut;
	size_t suffix_length;

	for (caller = 0U; caller < YT_ARRAY_LEN(callers); ++caller) {
		for (cut = DIRECT_WARP_ATTACK_FATAL_SPILL_RANDOM;
		    cut <= DIRECT_WARP_ATTACK_FATAL_SECTOR_PUT; ++cut) {
			CHECK(direct_warp_attack_fatal_prefix_setup(&viewer,
			    &stream, &fixture, &cycle, &attack, &combat,
			    callers[caller].main, callers[caller].ansi,
			    callers[caller].command, callers[caller].command_length,
			    remote, sizeof(remote), ends));
			CHECK(viewer.join.remote_length
			    == callers[caller].prefix_length);
			switch ((enum direct_warp_attack_fatal_prefix_cut)cut) {
			case DIRECT_WARP_ATTACK_FATAL_SPILL_RANDOM:
				attack.fail_random_at = 2U;
				break;
			case DIRECT_WARP_ATTACK_FATAL_SPILL_FIGHTER_ROW:
				attack.fail_spill_present_at = 1U;
				break;
			case DIRECT_WARP_ATTACK_FATAL_SPILL_SHIELD_ROW:
				attack.fail_spill_present_at = 2U;
				break;
			case DIRECT_WARP_ATTACK_FATAL_PLAYER_GET:
				attack.fail_persistence_player_read_at = 1U;
				break;
			case DIRECT_WARP_ATTACK_FATAL_PLAYER_PUT:
				attack.fail_persistence_player_write_at = 1U;
				break;
			case DIRECT_WARP_ATTACK_FATAL_SECTOR_GET:
				attack.fail_persistence_sector_read_at = 1U;
				break;
			case DIRECT_WARP_ATTACK_FATAL_SECTOR_PUT:
				attack.fail_persistence_sector_write_at = 1U;
				break;
			}
			yt_error_clear(&error);
			CHECK(!yt_hostile_attack_combat_run(&combat,
			    &direct_warp_attack_combat_ops, &attack, &error));
			suffix_length = viewer.join.remote_length
			    - callers[caller].prefix_length;
			CHECK(suffix_length
			    == expected[cut].length[callers[caller].ansi]
			    && viewer_bytes_fnv1a64(
			    remote + callers[caller].prefix_length, suffix_length)
			    == expected[cut].hash[callers[caller].ansi]
			    && viewer.join.local_row_count
			    == callers[caller].failure_rows
			    + (cut >= DIRECT_WARP_ATTACK_FATAL_SPILL_SHIELD_ROW ? 1U : 0U)
			    + (cut >= DIRECT_WARP_ATTACK_FATAL_PLAYER_GET ? 1U : 0U)
			    && viewer.join.local_color_count
			    == callers[caller].failure_colors
			    + (callers[caller].ansi
			    && cut >= DIRECT_WARP_ATTACK_FATAL_SPILL_SHIELD_ROW ? 1U : 0U)
			    + (callers[caller].ansi
			    && cut >= DIRECT_WARP_ATTACK_FATAL_PLAYER_GET ? 1U : 0U));
			CHECK(!combat.complete
			    && combat.route == YT_HOSTILE_ATTACK_COMBAT_NORMAL
			    && combat.attacker_loss == 1.0
			    && combat.defender_loss == 0.0
			    && combat.ship_fighters == 0.0
			    && combat.deployed_remaining == 2.0
			    && attack.spill_calls == 1U
			    && !attack.unexpected_fatal
			    && !attack.unexpected_tail_effect);
			CHECK(attack.random_calls == 2U
			    && attack.spill_stores
			    == (cut == DIRECT_WARP_ATTACK_FATAL_SPILL_RANDOM
			    ? 0U : 1U)
			    && attack.spill_present_calls
			    == (cut == DIRECT_WARP_ATTACK_FATAL_SPILL_RANDOM ? 0U
			    : cut == DIRECT_WARP_ATTACK_FATAL_SPILL_FIGHTER_ROW
			    ? 1U : 2U)
			    && attack.spill.iterations
			    == (cut == DIRECT_WARP_ATTACK_FATAL_SPILL_RANDOM ? 0U : 1U)
			    && attack.spill.fighter_row_presented
			    == (cut >= DIRECT_WARP_ATTACK_FATAL_SPILL_SHIELD_ROW)
			    && attack.spill.shield_row_presented
			    == (cut >= DIRECT_WARP_ATTACK_FATAL_PLAYER_GET)
			    && attack.spill.complete
			    == (cut >= DIRECT_WARP_ATTACK_FATAL_PLAYER_GET)
			    && combat.spill_called
			    == (cut >= DIRECT_WARP_ATTACK_FATAL_PLAYER_GET)
			    && combat.current.shields
			    == (cut == DIRECT_WARP_ATTACK_FATAL_SPILL_RANDOM ? 1.0f
			    : 0.0f)
			    && fixture.draw_position
			    == (cut == DIRECT_WARP_ATTACK_FATAL_SPILL_RANDOM
			    ? 8U : 9U));
			CHECK(attack.persistence_player_reads
			    == (cut >= DIRECT_WARP_ATTACK_FATAL_PLAYER_GET ? 1U : 0U)
			    && attack.persistence_player_writes
			    == (cut >= DIRECT_WARP_ATTACK_FATAL_PLAYER_PUT ? 1U : 0U)
			    && attack.persistence_sector_reads
			    == (cut >= DIRECT_WARP_ATTACK_FATAL_SECTOR_GET ? 1U : 0U)
			    && attack.persistence_sector_writes
			    == (cut >= DIRECT_WARP_ATTACK_FATAL_SECTOR_PUT ? 1U : 0U)
			    && combat.persistence.player_written
			    == (cut > DIRECT_WARP_ATTACK_FATAL_PLAYER_PUT)
			    && !combat.persistence.sector_written);
			if (cut >= DIRECT_WARP_ATTACK_FATAL_SECTOR_GET) {
				CHECK(attack.written_player.fighters == 0.0f
				    && attack.written_player.shields == 0.0f);
			}
			yt_text_input_destroy(&viewer.input);
		}
	}
}

