struct main_genesis_cycle_fixture {
	struct main_buy_cycle_fixture presentation;
	struct yt_player player;
	struct yt_genesis_state genesis;
	struct yt_genesis_handoff_state handoff;
	const uint8_t *answer;
	size_t answer_length;
	float required_ports;
	bool accepted;
	bool handoff_called;
	enum yt_genesis_handoff_operation handoff_failure;
	uint8_t handoff_file[64];
	size_t handoff_file_length;
	bool handoff_file5_open;
	bool handoff_closed_all;
	bool handoff_run_invoked;
};

static bool
main_genesis_hydrate(void *context, int player_record,
    struct yt_player *player, struct yt_error *error)
{
	struct main_genesis_cycle_fixture *fixture = context;

	(void)error;
	if (player_record != 2 || player == NULL)
		return false;
	*player = fixture->player;
	return true;
}

static bool
main_genesis_present(void *context, const uint8_t *text, size_t length,
    enum yt_genesis_output_kind kind, struct yt_error *error)
{
	struct main_genesis_cycle_fixture *fixture = context;
	struct viewer_pager_join *join = &fixture->presentation.viewer->join;

	(void)error;
	switch (kind) {
	case YT_GENESIS_PROPHECY_FIRST:
	case YT_GENESIS_DECLINED:
	case YT_GENESIS_INSUFFICIENT_FIRST:
		return normal_exit_line(join, NULL, 0U)
		    && normal_exit_b05d(join, text, length, 0.0f);
	case YT_GENESIS_PROPHECY_SECOND:
	case YT_GENESIS_INSUFFICIENT_SECOND:
		return normal_exit_b05d(join, text, length, 0.0f);
	case YT_GENESIS_PROMPT_BLANK:
	case YT_GENESIS_SUCCESS_BLANK:
		return normal_exit_line(join, NULL, 0U);
	case YT_GENESIS_DISABLED:
		if (!normal_exit_line(join, NULL, 0U))
			return false;
		join->presentation.bold = 1.0f;
		join->presentation.blink = 1.0f;
		join->queue[0] = '\0';
		join->queue_position = 0U;
		join->queue_length = 0U;
		return normal_exit_b05d(join, text, length, 0.0f);
	case YT_GENESIS_SUCCESS_FIRST:
	case YT_GENESIS_SUCCESS_SECOND:
		join->presentation.bold = 1.0f;
		return normal_exit_b05d(join, text, length, 0.0f);
	default:
		return false;
	}
}

static bool
main_genesis_confirm(void *context, const uint8_t *prompt, size_t length,
    bool *accepted, struct yt_error *error)
{
	struct main_genesis_cycle_fixture *fixture = context;
	struct viewer_pager_join *join = &fixture->presentation.viewer->join;
	struct yt_present_result result;

	(void)error;
	if (accepted == NULL || yt_present_character(prompt, length,
	    &join->presentation, &result) != YT_PRESENT_OK)
		return false;
	viewer_pager_capture_result(join, &result);
	if (!main_buy_present_answer(&fixture->presentation, fixture->answer,
	    fixture->answer_length))
		return false;
	*accepted = fixture->accepted;
	return true;
}

static bool
main_genesis_handoff_close_file5(void *context, struct yt_error *error)
{
	struct main_genesis_cycle_fixture *fixture = context;

	(void)error;
	/* Every source-reachable command-G entry has no live BASIC file 5. */
	fixture->handoff_file5_open = false;
	return true;
}

static bool
main_genesis_handoff_open_output(void *context, struct yt_error *error)
{
	struct main_genesis_cycle_fixture *fixture = context;

	(void)error;
	if (fixture->handoff_failure == YT_GENESIS_HANDOFF_OPEN_OUTPUT)
		return false;
	fixture->handoff_file_length = 0U;
	fixture->handoff_file5_open = true;
	return true;
}

static bool
main_genesis_handoff_print_command(void *context, struct yt_error *error)
{
	static const uint8_t command[] = "/BBS NODE1\r\n";
	struct main_genesis_cycle_fixture *fixture = context;

	(void)error;
	if (fixture->handoff_failure == YT_GENESIS_HANDOFF_PRINT_COMMAND)
		return false;
	memcpy(fixture->handoff_file, command, sizeof(command) - 1U);
	fixture->handoff_file_length = sizeof(command) - 1U;
	return true;
}

static bool
main_genesis_handoff_close_all(void *context, struct yt_error *error)
{
	struct main_genesis_cycle_fixture *fixture = context;

	(void)error;
	if (fixture->handoff_failure == YT_GENESIS_HANDOFF_CLOSE_ALL)
		return false;
	fixture->handoff_file[fixture->handoff_file_length++] = 0x1aU;
	fixture->handoff_file5_open = false;
	fixture->handoff_closed_all = true;
	return true;
}

static bool
main_genesis_handoff_run_program(void *context, struct yt_error *error)
{
	struct main_genesis_cycle_fixture *fixture = context;

	(void)error;
	fixture->handoff_run_invoked = true;
	return fixture->handoff_failure != YT_GENESIS_HANDOFF_RUN;
}

static bool
main_genesis_handoff(void *context, struct yt_error *error)
{
	static const struct yt_genesis_handoff_ops ops = {
		main_genesis_handoff_close_file5,
		main_genesis_handoff_open_output,
		main_genesis_handoff_print_command,
		main_genesis_handoff_close_all,
		main_genesis_handoff_run_program,
	};
	struct main_genesis_cycle_fixture *fixture = context;
	static const uint8_t old_file[] = "OLD\x1a";

	fixture->handoff_called = true;
	memcpy(fixture->handoff_file, old_file, sizeof(old_file) - 1U);
	fixture->handoff_file_length = sizeof(old_file) - 1U;
	fixture->handoff_file5_open = false;
	fixture->handoff_closed_all = false;
	fixture->handoff_run_invoked = false;
	return yt_genesis_handoff_run(&fixture->handoff, &ops, fixture,
	    error);
}

static const struct yt_genesis_ops main_genesis_ops = {
	main_genesis_hydrate,
	main_genesis_present,
	main_genesis_confirm,
	main_genesis_handoff,
};

static bool
main_genesis_cycle_run(struct main_genesis_cycle_fixture *fixture, bool ansi,
    size_t ends[3])
{
	static const uint8_t main_prompt[] =
	    "Time: 14:59  Main Command (?=Help)? ";
	static const uint8_t command[] = "gTrailing";
	struct viewer_pager_join *join = &fixture->presentation.viewer->join;

	join->presentation = state(ansi);
	join->presentation.foreground = 2.0f;
	join->presentation.color_initialized = 1.0f;
	join->presentation.cached_foreground = 2.0f;
	join->pager.foreground = 2;
	join->pager.line_count = 8.0f;
	if (!normal_exit_line(join, NULL, 0U)
	    || !normal_exit_b05d(join, main_prompt,
	    sizeof(main_prompt) - 1U, 1.0f))
		return false;
	yt_pager_editor_enter(&join->pager, join->accumulator,
	    sizeof(join->accumulator));
	if (!main_buy_present_echo(&fixture->presentation, command,
	    sizeof(command) - 1U) || !normal_exit_line(join, NULL, 0U))
		return false;
	ends[0] = join->remote_length;
	fixture->genesis = (struct yt_genesis_state){
		.current_player_record = 2,
		.required_ports = fixture->required_ports,
		.cached_trader = (const uint8_t *)"Captain Byte",
		.cached_trader_length = 12U,
	};
	if (!yt_genesis_run(&fixture->genesis, &main_genesis_ops, fixture,
	    NULL)) {
		if (fixture->handoff_failure == YT_GENESIS_HANDOFF_NONE
		    || fixture->handoff.failed_operation
		    != fixture->handoff_failure)
			return false;
		ends[1] = join->remote_length;
		ends[2] = ends[1];
		return true;
	}
	ends[1] = join->remote_length;
	if (fixture->genesis.route == YT_GENESIS_HANDOFF_ROUTE) {
		ends[2] = ends[1];
		return true;
	}
	if (!normal_exit_line(join, NULL, 0U)
	    || !normal_exit_b05d(join, main_prompt,
	    sizeof(main_prompt) - 1U, 1.0f))
		return false;
	yt_pager_editor_enter(&join->pager, join->accumulator,
	    sizeof(join->accumulator));
	ends[2] = join->remote_length;
	return true;
}

static void
test_main_genesis_decline_cycle_presentation(void)
{
	static const uint8_t expected[] =
	    "\r\nTime: 14:59  Main Command (?=Help)? gTrailing\r\n"
	    "\r\nIt has been written that one day a Trader Baron will rise up\n\r"
	    "and wipe the universe clean of the evil that infests it.\n\r"
	    "\r\nAre you that Trader Captain Byte [y/N]N\r\n"
	    "\r\nAlas, today is not the day that the prophesy will be fullfilled.\n\r"
	    "\r\nTime: 14:59  Main Command (?=Help)? ";
	static const size_t expected_ends[] = {49U, 282U, 320U};
	struct physical_viewer_join viewer;
	struct yt_file_viewer_stream_state stream;
	struct main_genesis_cycle_fixture fixture;
	uint8_t remote[350];
	size_t ends[3];
	size_t pass;

	for (pass = 0U; pass < 2U; ++pass) {
		memset(&viewer, 0, sizeof(viewer));
		fixture_viewer_initialize(&viewer, &stream,
		    retained_scoreboard, sizeof(retained_scoreboard) - 1U,
		    "YTSCORE.ASC", pass != 0U, remote, sizeof(remote));
		memset(&fixture, 0, sizeof(fixture));
		fixture.presentation.viewer = &viewer;
		fixture.player.ports_owned = 300.0f;
		fixture.answer = (const uint8_t *)"N";
		fixture.answer_length = 1U;
		fixture.required_ports = 300.0f;
		CHECK(main_genesis_cycle_run(&fixture, pass != 0U, ends));
		CHECK(memcmp(ends, expected_ends, sizeof(ends)) == 0
		    && viewer.join.remote_length == sizeof(expected) - 1U
		    && memcmp(remote, expected, sizeof(expected) - 1U) == 0);
		CHECK(fixture.genesis.complete
		    && fixture.genesis.route == YT_GENESIS_DECLINED_ROUTE
		    && fixture.genesis.player_hydrated
		    && fixture.genesis.confirmation_read
		    && !fixture.genesis.answer
		    && !fixture.genesis.disabled_presented
		    && !fixture.genesis.handoff_called
		    && !fixture.handoff_called);
		CHECK(viewer.join.presentation.foreground == 2.0f
		    && viewer.join.presentation.background == 0.0f
		    && viewer.join.presentation.bold == 0.0f
		    && viewer.join.presentation.blink == 0.0f
		    && viewer.join.presentation.cached_foreground == 2.0f
		    && viewer.join.pager.foreground == 2
		    && viewer.join.pager.line_count == 0.0f
		    && viewer.join.pager.nonstop == 0.0f
		    && viewer.join.local_fragment_length == 36U
		    && memcmp(viewer.join.local_fragment,
		    "Time: 14:59  Main Command (?=Help)? ", 36U) == 0
		    && viewer.join.accumulator[0] == '\0'
		    && viewer.join.queue_length == 0U);
		CHECK(viewer.join.local_row_count == 10U
		    && viewer_rows_fnv1a64(&viewer.join)
		    == UINT64_C(0xef88a21a14c77c44)
		    && viewer.join.local_color_count == (pass == 0U ? 5U : 18U)
		    && viewer_colors_fnv1a64(&viewer.join)
		    == (pass == 0U ? UINT64_C(0xc6f69f5cf097a0a2)
		    : UINT64_C(0xae89c4fc38bd168a)));
		yt_text_input_destroy(&viewer.input);
	}
	CHECK(sizeof(expected) - 1U == 320U);
}

static void
test_main_genesis_alternate_cycles_presentation(void)
{
	static const uint8_t opening[] =
	    "\r\nTime: 14:59  Main Command (?=Help)? gTrailing\r\n"
	    "\r\nIt has been written that one day a Trader Baron will rise up\n\r"
	    "and wipe the universe clean of the evil that infests it.\n\r"
	    "\r\nAre you that Trader Captain Byte [y/N]Y\r\n";
	static const uint8_t disabled_plain_tail[] =
	    "\r\n*FUNCTION DISABLED*\n\r"
	    "\r\nAlas, today is not the day that the prophesy will be fullfilled.\n\r"
	    "\r\nTime: 14:59  Main Command (?=Help)? ";
	static const uint8_t disabled_ansi_tail[] =
	    "\r\n\x1b[0;32;40;5;1m*FUNCTION DISABLED*\n\r"
	    "\x1b[0;32;40m\r\n"
	    "Alas, today is not the day that the prophesy will be fullfilled.\n\r"
	    "\r\nTime: 14:59  Main Command (?=Help)? ";
	static const uint8_t insufficient_tail[] =
	    "\r\nYou are not up to the challenge. You must own 300 ports before you are powerful\n\r"
	    "enough to initiate Genesis. You are 1 short of fulfilling the prophesy.\n\r"
	    "\r\nTime: 14:59  Main Command (?=Help)? ";
	static const struct {
		bool disabled;
		bool ansi;
		const uint8_t *tail;
		size_t tail_length;
		size_t total_length;
		enum yt_genesis_route route;
		size_t local_rows;
		uint64_t row_hash;
		size_t local_colors;
		uint64_t color_hash;
	} cases[] = {
		{true, false, disabled_plain_tail,
		    sizeof(disabled_plain_tail) - 1U, 343U,
		    YT_GENESIS_DISABLED_ROUTE, 12U,
		    UINT64_C(0x59c48b28fd5fbfd2), 6U,
		    UINT64_C(0x17798e683d05096d)},
		{true, true, disabled_ansi_tail,
		    sizeof(disabled_ansi_tail) - 1U, 367U,
		    YT_GENESIS_DISABLED_ROUTE, 12U,
		    UINT64_C(0x59c48b28fd5fbfd2), 21U,
		    UINT64_C(0xa3b23a9e42d2a82d)},
		{false, false, insufficient_tail,
		    sizeof(insufficient_tail) - 1U, 408U,
		    YT_GENESIS_INSUFFICIENT_ROUTE, 11U,
		    UINT64_C(0xbe08d08cd7e850d0), 6U,
		    UINT64_C(0x17798e683d05096d)},
		{false, true, insufficient_tail,
		    sizeof(insufficient_tail) - 1U, 408U,
		    YT_GENESIS_INSUFFICIENT_ROUTE, 11U,
		    UINT64_C(0xbe08d08cd7e850d0), 20U,
		    UINT64_C(0x4ea7870caf4939ed)},
	};
	struct physical_viewer_join viewer;
	struct yt_file_viewer_stream_state stream;
	struct main_genesis_cycle_fixture fixture;
	uint8_t expected[450];
	uint8_t remote[450];
	size_t ends[3];
	size_t pass;

	for (pass = 0U; pass < YT_ARRAY_LEN(cases); ++pass) {
		memcpy(expected, opening, sizeof(opening) - 1U);
		memcpy(expected + sizeof(opening) - 1U, cases[pass].tail,
		    cases[pass].tail_length);
		memset(&viewer, 0, sizeof(viewer));
		fixture_viewer_initialize(&viewer, &stream,
		    retained_scoreboard, sizeof(retained_scoreboard) - 1U,
		    "YTSCORE.ASC", cases[pass].ansi, remote, sizeof(remote));
		memset(&fixture, 0, sizeof(fixture));
		fixture.presentation.viewer = &viewer;
		fixture.player.ports_owned = cases[pass].disabled
		    ? 300.0f : 299.0f;
		fixture.answer = (const uint8_t *)"Y";
		fixture.answer_length = 1U;
		fixture.required_ports = cases[pass].disabled ? 301.0f : 300.0f;
		fixture.accepted = true;
		CHECK(main_genesis_cycle_run(&fixture, cases[pass].ansi, ends));
		CHECK(sizeof(opening) - 1U + cases[pass].tail_length
		    == cases[pass].total_length
		    && viewer.join.remote_length == cases[pass].total_length
		    && memcmp(remote, expected, cases[pass].total_length) == 0
		    && ends[0] == 49U
		    && ends[1] == cases[pass].total_length - 38U
		    && ends[2] == cases[pass].total_length);
		CHECK(fixture.genesis.complete
		    && fixture.genesis.route == cases[pass].route
		    && fixture.genesis.player_hydrated
		    && fixture.genesis.confirmation_read
		    && !fixture.genesis.handoff_called
		    && !fixture.handoff_called
		    && fixture.genesis.disabled_presented == cases[pass].disabled
		    && fixture.genesis.answer == !cases[pass].disabled);
		CHECK(viewer.join.presentation.foreground == 2.0f
		    && viewer.join.presentation.background == 0.0f
		    && viewer.join.presentation.bold
		    == (cases[pass].disabled && !cases[pass].ansi ? 1.0f : 0.0f)
		    && viewer.join.presentation.blink
		    == (cases[pass].disabled && !cases[pass].ansi ? 1.0f : 0.0f)
		    && viewer.join.presentation.cached_foreground == 2.0f
		    && viewer.join.pager.foreground == 2
		    && viewer.join.pager.line_count == 0.0f
		    && viewer.join.pager.nonstop == 0.0f
		    && viewer.join.local_fragment_length == 36U
		    && memcmp(viewer.join.local_fragment,
		    "Time: 14:59  Main Command (?=Help)? ", 36U) == 0
		    && viewer.join.accumulator[0] == '\0');
		CHECK(viewer.join.local_row_count == cases[pass].local_rows
		    && viewer_rows_fnv1a64(&viewer.join) == cases[pass].row_hash
		    && viewer.join.local_color_count == cases[pass].local_colors
		    && viewer_colors_fnv1a64(&viewer.join)
		    == cases[pass].color_hash);
		yt_text_input_destroy(&viewer.input);
	}
}

