	CHECK(yt_present_editor_echo((const uint8_t *)"6", 1,
	    (const uint8_t *)"6", 1, &current, &result) == YT_PRESENT_OK);
	pager_capture_result(&capture, &result);
	CHECK(yt_present_line(NULL, 0, &current, &result) == YT_PRESENT_OK);
	pager_capture_result(&capture, &result);
	CHECK(yt_present_line(NULL, 0, &current, &result) == YT_PRESENT_OK);
